  ["~%d h %d min"] = "~%d Std. %d Min.",
  ["%s fabricando"] = "%s Herstellen",
  ["La ruta más barata, aunque pida más fabricaciones."] = "Die günstigste Route, auch wenn sie mehr Herstellungen braucht.",
