  ["Anúncialo desde la ventana de la Casa de Subastas."] = "Stelle es vom Fenster des Auktionshauses aus ein.",
  ["Escaneando la AH (%d%%): espera a que acabe para anunciar al precio de ahora."] = "Scanne das AH (%d%%): warte, bis es fertig ist, um zu aktuellen Preisen einzustellen.",
  ["Escaneando la AH (%d%%): espera para anunciar al precio de ahora."] = "Scanne das AH (%d%%): warte, um zu aktuellen Preisen einzustellen.",
  ["Precios de hace %d h: pueden haber cambiado. Escanea antes de anunciar."] = "Preise von vor %d h: sie können sich geändert haben. Scanne vor dem Einstellen.",
  ["Escaneando la AH... %d%%"] = "Scanne das AH... %d %%",
  ["Actualizando los precios..."] = "Preise werden aktualisiert...",
  ["Espera para anunciar: al acabar, los precios se actualizan solos."] = "Warte mit dem Einstellen: Danach aktualisieren sich die Preise von selbst.",
  ["Escaneando la AH: espera a que acabe para anunciarlo."] = "Scanne das AH: warte, bis es fertig ist, um es einzustellen.",
  ["Precio del escaneo de la AH de %s."] = "Preis aus dem AH-Scan %s.",
  ["No se pudo anunciar: "] = "Einstellen fehlgeschlagen: ",
  ["La Casa de Subastas está ocupada: vuelve a pulsar en un momento."] = "Das Auktionshaus ist beschäftigt: klicke gleich noch einmal.",
  ["La Casa de Subastas ya está lista: vuelve a pulsar."] = "Das Auktionshaus ist bereit: klicke erneut.",
  ["Anunciados %d de %s a %s cada uno (%d h)."] = "%d %s zu je %s eingestellt (%d h).",
  ["Subasta de %d h: no se sabe si se vende y, si caduca, pierdes solo %s de depósito por subasta."] = "Auktion über %d h: ob es sich verkauft, ist unklar, und läuft sie ab, verlierst du nur %s Anzahlung pro Auktion.",
  ["No llevas %s en las bolsas."] = "Du hast kein %s in deinen Taschen.",
  ["Lo que tienes se usa primero; el resto se compra (arriba)"] = "Was du hast, wird zuerst genutzt; der Rest wird gekauft (oben)",
  ["Empezar ruta"] = "Route beginnen",
  ["Fija esta ruta: mientras compras en la AH, al vendedor o sacas del correo, ni la ruta ni su coste cambian. La lista de la compra va marcando lo que te falta."] = "Legt diese Route fest: während du im AH, beim Händler kaufst oder Post abholst, ändern sich weder die Route noch ihre Kosten. Die Einkaufsliste hält fest, was dir noch fehlt.",
  ["Púlsalo antes de empezar a comprar."] = "Klicke darauf, bevor du anfängst zu kaufen.",
  ["Ruta en curso (de %d a %d): lo que compras no cambia la ruta ni su coste"] = "Route läuft (%d bis %d): was du kaufst, ändert weder die Route noch ihre Kosten",
  [" · hay precios nuevos de la AH|r"] = " · neue AH-Preise|r",
  [" · precios nuevos: %s más|r"] = " · neue Preise: %s mehr|r",
  [" · precios nuevos: %s menos|r"] = " · neue Preise: %s weniger|r",
  ["Con el último escaneo, lo que te queda cuesta %s (con los precios de tu ruta, %s)."] = "Mit deinem letzten Scan kostet der Rest deiner Route %s (%s mit den Preisen deiner Route).",
  ["Con el último escaneo, lo que te queda de tu ruta de %s cuesta %s más (%s en vez de %s). Ábrela y pulsa Actualizar precios para verla con estos precios."] = "Mit deinem letzten Scan kostet der Rest deiner Route für %s %s mehr (%s statt %s). Öffne sie und klicke auf Preise aktualisieren, um sie mit diesen Preisen zu sehen.",
  ["Actualizar precios"] = "Preise aktualisieren",
  ["La misma ruta (mismas recetas en cada nivel) con los precios del último escaneo. Lo que llevas gastado y vendido se mantiene."] = "Dieselbe Route (gleiche Rezepte auf jeder Stufe) mit den Preisen des letzten Scans. Was du bisher ausgegeben und verkauft hast, bleibt erhalten.",
  
  [" · pulsa Empezar ruta antes de comprar|r"] = " · klicke vor dem Kaufen auf Route beginnen|r",
  ["Hecho"] = "Fertig",
  ["precio desconocido"] = "Preis unbekannt",
  ["Aún no se sabe dónde está %s: es nuevo de Forever y las bases de datos no lo tienen situado."] = "Der Standort von %s ist noch unbekannt: es ist neu in Forever und die Datenbanken haben es noch nicht verortet.",
