  ["La ruta busca otra receta en su lugar (por ejemplo, si no quieres ir a por este pergamino)."] = "Die Route sucht stattdessen ein anderes Rezept (zum Beispiel, wenn du dieses Muster nicht holen willst).",
  ["Recetas quitadas de la ruta: %d"] = "Aus der Route entfernte Rezepte: %d",
  ["Avisos ocultos: %d"] = "Ausgeblendete Hinweise: %d",
