  [" y "] = " und ",
  ["Aprendida"] = "Erlernt",
  ["solo gastas %s en el instructor y el vendedor"] = "du gibst nur %s beim Lehrer und Händler aus",
  ["no gastas oro"] = "du gibst kein Gold aus",
  [" (más el instructor, precio desconocido)"] = " (plus Lehrer, Preis unbekannt)",
  ["Con lo que llevas podrías hacer %s (%d–%d): %s, pero usas %s, por los que te darían unos %s vendiéndolos."] = "Mit dem, was du hast, könntest du %s herstellen (%d–%d): %s, aber du verbrauchst %s, das dir beim Verkauf etwa %s bringen würde.",
  ["Hacerla con lo tuyo te sale unos %s mejor que venderlo y seguir la ruta. Pulsa Dejar ruta para incluirla."] = "Es mit deinem herzustellen ist etwa %s besser, als es zu verkaufen und der Route zu folgen. Klicke auf Route verlassen, um es einzubeziehen.",
  ["Vender lo tuyo y seguir la ruta te sale unos %s mejor."] = "Deins zu verkaufen und der Route zu folgen ist etwa %s besser.",
  ["Sale casi igual que venderlo, así que es más cómodo usar lo tuyo. Pulsa Dejar ruta para incluirla."] = "Es ist etwa gleich wie verkaufen, also ist es einfacher, deins zu nutzen. Klicke auf Route verlassen, um es einzubeziehen.",
  ["Informar de un error"] = "Fehler melden",
  ["¿Has visto información incorrecta, un error o algo nuevo que falte? Cuéntalo en el Discord con una captura de pantalla."] = "Falsche Informationen, ein Fehler oder etwas Neues, das fehlt? Melde es in unserem Discord mit einem Screenshot.",
  ["Discord (Ctrl+C para copiar):"] = "Discord (Strg+C zum Kopieren):",
  ["Errores, datos incorrectos o sugerencias: en nuestro Discord."] = "Fehler, falsche Daten oder Vorschläge: in unserem Discord.",
  ["nunca"] = "nie",
