  -- HeaderUI
  ["Sin resultados"] = "Keine Ergebnisse",
  ["Idioma del addon"] = "Sprache des Addons",
  ["Último escaneo: "] = "Letzter Scan: ",
  ["El servidor solo permite un escaneo completo cada 15 min: podrás volver a escanear en %s."] = "Der Server erlaubt nur einen vollständigen Scan alle 15 Min.: du kannst wieder scannen in %s.",
  ["El servidor no respondió: solo permite un escaneo completo cada 15 min. Podrás volver a escanear en %s."] = "Der Server hat nicht geantwortet: er erlaubt nur einen vollständigen Scan alle 15 Min. Du kannst wieder scannen in %s.",
  ["Sin escanear"] = "Nicht gescannt",
  ["Registro de errores vaciado."] = "Fehlerprotokoll geleert.",
  ["Su ruta se calcula al abrirla (solo se calculan solas las profesiones que tienes)."] = "Seine Route wird beim Öffnen berechnet (nur deine eigenen Berufe werden automatisch berechnet).",
  ["Ningún error registrado."] = "Keine Fehler protokolliert.",
  ["%d errores distintos registrados (el más reciente al final):"] = "%d verschiedene Fehler protokolliert (der neueste zuletzt):",
  ["Detalle completo en CraftersJournalDB.errorLog (SavedVariables, tras /reload). /cj errores borrar para vaciarlo."] = "Alle Details in CraftersJournalDB.errorLog (SavedVariables, nach /reload). Gib /cj errors clear ein, um es zu leeren.",
  ["Grabando los errores de Lua del addon hasta la próxima recarga (/reload). Repite lo que fallaba y mira /cj errores."] = "Die Lua-Fehler des Addons werden bis zum nächsten Neuladen (/reload) aufgezeichnet. Wiederhole, was fehlschlug, und sieh in /cj errors nach.",
  ["Grabando los errores de Lua del addon hasta la próxima recarga (/reload)."] = "Die Lua-Fehler des Addons werden bis zum nächsten Neuladen (/reload) aufgezeichnet.",
  ["Los errores de Lua del addon solo se graban con /cj errores grabar (hasta la próxima recarga)."] = "Die Lua-Fehler des Addons werden nur nach /cj errors record aufgezeichnet (bis zum nächsten Neuladen).",
  ["Clic: vender %d por %s."] = "Klick: %d für %s verkaufen.",
  ["Vendiendo…"] = "Verkaufe…",
  ["Para vender al vendedor, de tus bolsas:"] = "An den Händler verkaufen, aus deinen Taschen:",
  ["Vendiendo %d objetos por %s..."] = "Verkaufe %d Gegenstände für %s...",
  ["Vender las %d (%s)"] = "Alle %d verkaufen (%s)",
  ["Instructor donde la viste"] = "Lehrer, bei dem du es gesehen hast",
  ["Instructor del rango siguiente"] = "Lehrer des nächsten Rangs",
  ["Instructor del rango siguiente (el de su rango no la tiene)"] = "Lehrer des nächsten Rangs (der Lehrer des eigenen Rangs hat es nicht)",
  ["Tu ruta de %s usaba %s, que este instructor no enseña: se calcula otra desde tu nivel."] = "Deine Route für %s nutzte %s, das dieser Lehrer nicht lehrt: es wird eine neue Route ab deiner Stufe berechnet.",
  ["Tu ruta de %s ya no se puede seguir con lo que enseña este instructor: se calcula otra desde tu nivel."] = "Deine Route für %s lässt sich mit dem, was dieser Lehrer lehrt, nicht mehr verfolgen: es wird eine neue Route ab deiner Stufe berechnet.",
  ["No puedes aprender %s: ya tienes dos profesiones principales. Olvida una primero (desde su ventana de profesión)."] = "Du kannst %s nicht erlernen: Du hast bereits zwei Hauptberufe. Verlerne zuerst einen (in seinem Berufsfenster).",
  ["Vender al vendedor"] = "An den Händler verkaufen",
  ["Vendes %d × %s"] = "Du verkaufst %d × %s",
  ["Vender todo (%s)"] = "Alles verkaufen (%s)",
  ["Vender todo"] = "Alles verkaufen",
  ["Vende todo lo de esta lista: lo de tus bolsas que el vendedor compra, salvo lo que necesitan tus rutas empezadas, las herramientas, tu equipo (si lo activas en las opciones) y lo que marques con clic derecho (no venderlo nunca). Mira la lista antes de pulsar."] = "Verkauft alles auf dieser Liste: alles in deinen Taschen, was der Händler kauft, außer was deine begonnenen Routen brauchen, Berufswerkzeugen, deiner eigenen Ausrüstung (falls in den Optionen aktiviert) und dem, was du per Rechtsklick markierst (nie verkaufen). Prüfe die Liste, bevor du klickst.",
  ["Para que esta ventana no salga: su engranaje, o las opciones del addon (engranaje de la ventana principal o /cj opciones)."] = "Damit dieses Fenster nicht erscheint: sein Zahnrad oder die Addon-Optionen (Zahnrad im Hauptfenster oder /cj options).",
  -- Options window
  ["General"] = "Allgemein",
  ["Casa de Subastas"] = "Auktionshaus",
  ["Versión %s"] = "Version %s",
  ["Únete a nuestro Discord"] = "Tritt unserem Discord bei",
  ["Ideas, errores y novedades"] = "Ideen, Fehler und Neuigkeiten",
  ["Novedades, ideas y ayuda con el addon. Copia el enlace y ábrelo en tu navegador."] = "Neuigkeiten, Ideen und Hilfe zum Addon. Kopiere den Link und öffne ihn in deinem Browser.",
  ["Ventanas, qué se propone vender, avisos y botón del minimapa."] = "Fenster, was zum Verkauf vorgeschlagen wird, Hinweise und der Minikartenknopf.",
  ["No vender tu equipo"] = "Deine Ausrüstung nicht verkaufen",
  ["Activado, el equipo ligado a ti (tu otro equipo, lo de las misiones) y el de los conjuntos del gestor de equipo no se propone vender (ni Vender todo lo vende); los verdes sin ligar de botín, lo que fabricas y lo gris, sí. Desactivado, se propone todo: lo que quieras guardar, clic derecho y no se vende nunca."] = "Aktiviert werden seelengebundene Ausrüstung (dein anderes Set, Questbelohnungen) und Ausrüstung in deinen Ausrüstungssets nicht zum Verkauf vorgeschlagen (und Alles verkaufen verkauft sie nicht); ungebundene grüne Beute, Hergestelltes und Graues schon. Deaktiviert wird alles vorgeschlagen: klicke rechts auf das, was du behalten willst, dann wird es nie verkauft.",
  ["Avisos en el chat"] = "Chat-Hinweise",
  ["Vendedores de recetas de stock limitado"] = "Rezepthändler mit begrenztem Vorrat",
  ["La ruta cuenta con ellos: suele ser lo más barato. Venden pocas y reponen con el tiempo, y a veces otros jugadores las acaparan para revenderlas."] = "Die Route zählt auf sie: meist die günstigste Option. Sie verkaufen nur wenige und füllen mit der Zeit nach, und andere Spieler kaufen manchmal alle auf, um sie weiterzuverkaufen.",
  ["La ruta no cuenta con ellos: esas recetas solo se consiguen por misión o en la Casa de Subastas; si no, se usa otra receta."] = "Die Route zählt nicht auf sie: diese Rezepte kommen nur aus einer Quest oder dem Auktionshaus; sonst nutzt sie ein anderes Rezept.",
  ["Su vendedor tiene stock limitado y desactivaste esos vendedores con su icono, arriba de la ruta."] = "Sein Händler hat begrenzten Vorrat, und du hast diese Händler mit ihrem Symbol über der Route ausgeschaltet.",
  ["Clic: abrir la receta y fabricar %d (con la profesión cerrada, el primer clic la abre)."] = "Klick: Rezept öffnen und %d herstellen (ist das Berufsfenster zu, öffnet es der erste Klick).",
  ["Clic derecho: añadir sus materiales a la lista de compra."] = "Rechtsklick: seine Materialien zur Einkaufsliste hinzufügen.",
  ["Ventana junto a la profesión"] = "Fenster neben Berufen",
  ["Al abrir una profesión: lo que la pestaña Ganar dinero propone fabricar de esa profesión. Clic en una fila para fabricarlo."] = "Beim Öffnen eines Berufs: was der Reiter Geld verdienen damit herzustellen vorschlägt. Klicke auf eine Zeile, um es herzustellen.",
  ["Ganar dinero · %s: lo que da beneficio fabricar"] = "Geld verdienen · %s: was sich herzustellen lohnt",
  ["vender en la AH · invierte %s"] = "im AH verkaufen · investiere %s",
  ["vender al vendedor · invierte %s"] = "an einen Händler verkaufen · investiere %s",
  ["Clic: fabricar las de la fila (como mucho, las que dan tus materiales)."] = "Klick: die Menge der Zeile herstellen (höchstens so viele, wie deine Materialien erlauben).",
  ["(%d más en la pestaña Ganar dinero)"] = "(%d weitere im Reiter Geld verdienen)",
  ["Fabricarlo (sus materiales)"] = "Herstellen (aus seinen Materialien)",
  ["Comprarlo hecho"] = "Fertig kaufen",
  ["sin precio"] = "kein Preis",
  ["Lo más barato: comprarlo hecho."] = "Am günstigsten: fertig kaufen.",
  ["Lo más barato: fabricarlo."] = "Am günstigsten: herstellen.",
  ["Tiene enfriamiento (una cada pocos días): se compra hecho si se puede."] = "Hat eine Abklingzeit (eins alle paar Tage): wird möglichst fertig gekauft.",
  ["Clic: comprarlo hecho en vez de fabricarlo."] = "Klick: fertig kaufen statt herstellen.",
  ["Clic: fabricarlo en vez de comprarlo hecho."] = "Klick: herstellen statt fertig kaufen.",
  ["lo fabricas"] = "du stellst es her",
  ["lo compras hecho"] = "du kaufst es fertig",
  [" · no es lo más barato"] = " · nicht das günstigste",
  [" · clic para cambiar"] = " · klicken zum Ändern",
  ["En la AH"] = "Im AH",
  ["Por el chat de comercio (sin comisión)"] = "Über den Handelschat (ohne Gebühr)",
  ["Al vendedor"] = "An einen Händler",
  ["Depósito: %s (%d subastas de %d h). Se devuelve si se vende: no resta del beneficio; lo pierdes si caduca."] = "Anzahlung: %s (%d Auktionen à %d h). Du bekommst sie zurück, wenn es sich verkauft, daher wird sie nicht vom Gewinn abgezogen; läuft es ab, verlierst du sie.",
  ["Vender en:"] = "Verkaufen über:",
  ["AH · %d h"] = "AH · %d h",
  ["Cara a cara (comercio): sin comisión de la AH ni depósito."] = "Direkt (Handel): keine AH-Gebühr und keine Anzahlung.",
  ["Fabricar más"] = "Mehr herstellen",
  ["Clic: escribir el precio por unidad"] = "Klick: Preis pro Stück eingeben",
  ["Por ejemplo 6.5 (6s 50c) o 1g 20s. Vacío vuelve al precio automático; Escape no cambia nada."] = "Zum Beispiel 6.5 (6s 50k) oder 1g 20s. Leer setzt den automatischen Preis zurück; Escape ändert nichts.",
  ["Fabricar menos"] = "Weniger herstellen",
  ["Con Mayús, de 5 en 5. Tu cantidad dura hasta el siguiente escaneo; luego vuelve a la recomendada."] = "Umschalt: 5 auf einmal. Deine Menge gilt bis zum nächsten Scan, danach wieder die empfohlene.",
  [" · más de lo recomendado (%d)"] = " · mehr als empfohlen (%d)",
  ["Fabrica %d: la cantidad la elegiste tú (recomendadas: %d). Vuelve a la recomendada con el siguiente escaneo."] = "%d herstellen: diese Menge hast du gewählt (empfohlen: %d). Mit dem nächsten Scan wird es wieder die empfohlene.",
  ["Más de lo recomendado: si no se venden, tienes el oro parado y puedes perder depósitos al caducar."] = "Mehr als empfohlen: verkauft es sich nicht, ist dein Gold gebunden, und du kannst Anzahlungen verlieren, wenn sie ablaufen.",
  ["%s: quitada de la Lista de compra. Tu ruta sigue empezada; vuelve a ponerla desde la vista Materiales de la ruta."] = "%s: von der Einkaufsliste entfernt. Deine Route ist weiter begonnen; füge sie in der Materialansicht der Route wieder hinzu.",
  ["Quitar la lista de esta ruta. La ruta sigue empezada; se vuelve a poner desde su vista Materiales."] = "Die Liste dieser Route entfernen. Die Route bleibt begonnen; füge sie in ihrer Materialansicht wieder hinzu.",
  ["Lista de compra · quitada"] = "Einkaufsliste · entfernt",
  ["Pulsa para volver a ponerla"] = "Klicken, um sie wieder hinzuzufügen",
  ["la quitaste con la X de la Lista de compra"] = "du hast sie mit dem X in der Einkaufsliste entfernt",
  [" · pide objetos"] = " · verlangt Gegenstände",
  [" · cadena de %d misiones"] = " · Kette aus %d Quests",
  ["Pide: "] = "Verlangt: ",
  ["Antes hay que hacer 1 misión de su cadena, que también puede pedir objetos."] = "Du musst zuerst 1 vorherige Quest der Kette erledigen, die ebenfalls Gegenstände verlangen kann.",
  ["Antes hay que hacer %d misiones de su cadena, que también pueden pedir objetos."] = "Du musst zuerst %d vorherige Quests der Kette erledigen, die ebenfalls Gegenstände verlangen können.",
  ["La ruta no le pone precio a lo que pide (casi todo se consigue matando criaturas). Si no te compensa, quítala con la X de la fila."] = "Die Route bepreist nicht, was sie verlangt (das meiste droppt von Gegnern). Lohnt es sich für dich nicht, entferne sie mit dem X in der Zeile.",
  ["stock limitado · no se cuentan"] = "begrenzter Vorrat · nicht genutzt",
  ["X de la fila: quitar esta receta y que la ruta busque otra (se recupera con la fila de recetas quitadas)."] = "X in der Zeile: dieses Rezept entfernen und die Route ein anderes wählen lassen (zurückholen über die Zeile der entfernten Rezepte).",
  ["Tras un escaneo: recetas de botín que te faltan y están en la AH, y si tu ruta empezada cuesta bastante más con los precios nuevos. Desactivados, la ruta lo sigue diciendo en su línea de estado."] = "Nach einem Scan: Beuterezepte, die dir fehlen und im AH sind, und ob deine begonnene Route mit den neuen Preisen viel mehr kostet. Deaktiviert zeigt es die Route weiterhin in ihrer Statuszeile.",
  ["Botón del minimapa"] = "Minikartenknopf",
  ["El botón de Crafter's Journal junto al minimapa. También con /cj minimap."] = "Der Crafter's-Journal-Knopf an der Minikarte. Auch mit /cj minimap.",
  ["Tu equipo (ligado a ti o en un conjunto del gestor de equipo): no se propone venderlo, para no venderlo sin querer. Se cambia en /cj opciones."] = "Deine Ausrüstung (seelengebunden oder in einem Ausrüstungsset): wird nicht zum Verkauf vorgeschlagen, damit du sie nicht aus Versehen verkaufst. Ändern mit /cj options.",
  ["tu equipo: no se vende"] = "deine Ausrüstung: nicht zu verkaufen",
  ["Ventana junto al vendedor"] = "Fenster neben Händlern",
  ["Al abrir un vendedor: lo que te falta de la lista de compra y lo que puedes venderle, con los botones Comprar todo y Vender todo."] = "Beim Ansprechen eines Händlers: was dir von deiner Einkaufsliste noch fehlt und was du ihm verkaufen kannst, mit den Knöpfen Alles kaufen und Alles verkaufen.",
  ["Lista de compra junto a la Casa de Subastas"] = "Einkaufsliste neben dem Auktionshaus",
  ["Tamaño de las tandas (recetas verdes)"] = "Chargengröße (grüne Rezepte)",
  ["En verde no todas las fabricaciones suben punto: la ruta compra para unas tantas y, al gastarlas, la siguiente. Más grande, menos viajes a la AH; más pequeña, menos material de sobra si tienes suerte."] = "Bei grünen Rezepten gibt nicht jede Herstellung einen Punkt: die Route kauft für eine bestimmte Anzahl und, wenn du sie aufgebraucht hast, die nächste Charge. Größer heißt weniger Wege zum AH; kleiner heißt weniger übrige Materialien, wenn du Glück hast.",
  ["Cada tanda es de unas %d fabricaciones: se cambia en /cj opciones, Lista de compra."] = "Jede Charge umfasst etwa %d Herstellungen: änderbar unter /cj Optionen, Einkaufsliste.",
  ["Al abrir la AH: los materiales de tu ruta que te faltan, para comprarlos. Desactivada, se sigue pudiendo abrir con el botón de encima de la AH."] = "Beim Öffnen des AH: die Materialien, die deine Route noch braucht, bereit zum Kaufen. Deaktiviert kannst du sie weiterhin mit dem Knopf über dem AH öffnen.",
  ["Vender en la AH desde tus bolsas"] = "Im AH aus deinen Taschen verkaufen",
  ["Opciones"] = "Optionen",
  -- WhatsNew
  ["Novedades"] = "Neuigkeiten",
  ["Crafter's Journal %s: esto es lo nuevo desde la última vez."] = "Crafter's Journal %s: das ist neu seit dem letzten Mal.",
  ["¡Entendido!"] = "Verstanden!",
  ["Siguiente"] = "Weiter",
  ["Precios del vendedor, siempre los del juego"] = "Händlerpreise, immer die des Spiels",
  ["El addon ya no deduce lo que paga el vendedor del dinero que te entra al vender: con dos ventas cobradas juntas podía apuntar el doble, y Ganar dinero prometía de más. Ahora usa siempre el precio del juego."] = "Das Addon leitet nicht mehr aus dem Geld beim Verkaufen ab, was Händler zahlen: Zwei gleichzeitig bezahlte Verkäufe konnten den doppelten Preis ergeben, und Geld verdienen versprach zu viel. Jetzt nutzt es immer den Preis des Spiels.",
  ["Aprender una receta, solo si compensa"] = "Ein Rezept lernen, nur wenn es sich lohnt",
  ["La ruta ya no te manda al instructor a aprender una receta para unas pocas fabricaciones que ahorran unas monedas: esos puntos los hace con la receta de al lado, salvo que ahorre más de 5s."] = "Die Route schickt dich nicht mehr zum Lehrer, um ein Rezept für ein paar Herstellungen zu lernen, die nur ein paar Münzen sparen: Diese Punkte macht sie mit dem Rezept daneben, außer es spart mehr als 5s.",
  ["Se ve cuándo esperar en la AH"] = "Sehen, wann man im AH warten muss",
  ["Mientras se escanea la AH, la ventana de vender queda tapada con un reloj de arena y el progreso: así no anuncias a precios viejos sin querer."] = "Während das AH gescannt wird, ist das Verkaufsfenster mit einer Sanduhr und dem Fortschritt abgedeckt: So stellst du nicht versehentlich zu alten Preisen ein.",
  ["Nueva pestaña: Merchant's Favor"] = "Neuer Reiter: Merchant's Favor",
  ["Con qué llenar tus Waylaid Crates al menor coste y qué cajas de la AH dan el Favor más barato por punto. Clic en una fila para añadirlo a la lista de compra."] = "Womit du deine Waylaid Crates am günstigsten füllst und welche Kisten im AH den günstigsten Favor pro Punkt geben. Klick auf eine Zeile, um es zur Einkaufsliste hinzuzufügen.",
  ["Más fluido"] = "Flüssiger",
  ["Sin tirones al acabar un escaneo ni al entrar, fabricar en serie va fluido y el addon apenas trabaja mientras juegas por el mundo."] = "Keine Ruckler mehr am Ende eines Scans oder beim Einloggen, Serienherstellung läuft flüssig, und das Addon arbeitet kaum, während du in der Welt spielst.",
  ["Cuánto se tarda en fabricar"] = "Wie lange das Herstellen dauert",
  ["Cada paso de la ruta dice cuánto se tarda en fabricarlo (en naranja si es lento) y el total, el de toda la ruta. \"Menos fabricaciones\" ahora también evita las recetas lentas."] = "Jeder Routenschritt zeigt, wie lange das Herstellen dauert (orange, wenn es langsam ist), und die Summe die ganze Route. \"Weniger Herstellungen\" meidet jetzt auch langsame Rezepte.",
  ["Ganar dinero, más fiable"] = "Geld verdienen, zuverlässiger",
  ["Solo fabrica lo intermedio con recetas que sabes y dice qué fabricar antes. Enseña cuánto ya llevas en las bolsas, y las filas del lote no cambian de sitio al pulsar - o +."] = "Zwischenprodukte stellt es nur mit Rezepten her, die du kennst, und sagt, was zuerst herzustellen ist. Es zeigt, was du schon in den Taschen hast, und die Zeilen verschieben sich bei - oder + nicht mehr.",
  ["Quitar una ventana, en un clic"] = "Ein Fenster mit einem Klick ausschalten",
  ["El engranaje de las ventanas junto al vendedor, la AH y la profesión abre un menú con \"No mostrar esta ventana\", sin buscarla en las opciones."] = "Das Zahnrad an den Fenstern neben dem Händler, dem AH und dem Beruf öffnet ein Menü mit \"Fenster nicht mehr anzeigen\", ohne in den Optionen zu suchen.",
  ["Buscar en la AH con Mayús+clic"] = "Im AH suchen mit Umschalt+Klick",
  ["Mayús+clic en un objeto del addon lo busca en la AH (o lo enlaza en el chat). Y la lista de compra junto a la AH tiene una X en cada lista para quitarla."] = "Umschalt+Klick auf einen Gegenstand im Addon sucht ihn im AH (oder verlinkt ihn im Chat). Und die Einkaufsliste neben dem AH hat bei jeder Liste ein X zum Entfernen.",
  ["Vista de desarrollo: no cuenta como vista."] = "Entwicklervorschau: nicht als gesehen markiert.",
  ["Ahora en alemán y francés"] = "Jetzt auf Deutsch und Französisch",
  ["Textos, recetas y objetos en alemán y francés, con los nombres del juego. Se cambia con el selector de idioma de arriba. Si ves una traducción mejorable, dínoslo en Discord."] = "Texte, Rezepte und Gegenstände auf Deutsch und Französisch, mit den Namen aus dem Spiel. Umschalten mit der Sprachauswahl oben. Wenn dir eine Übersetzung nicht gefällt, sag es uns im Discord.",
  ["Cada ventana, con su propia opción"] = "Jedes Fenster hat seine eigene Option",
  ["Las ventanas que salen solas junto al vendedor, la Casa de Subastas y la profesión tienen un engranaje que abre las opciones. La lista de compra y la de vender en la AH ya se quitan por separado."] = "Die Fenster, die sich neben Händlern, dem Auktionshaus und deinem Beruf öffnen, haben jetzt ein Zahnrad, das die Optionen öffnet. Die Einkaufsliste und das AH-Verkaufsfenster lassen sich getrennt ausschalten.",
  ["Confirmar antes de anunciar"] = "Vor dem Einstellen bestätigen",
  ["Al anunciar más de una unidad de golpe se pregunta antes cuántas y a qué precio. Así un clic sin querer no anuncia un montón. Se puede desactivar."] = "Wenn du mehr als ein Stück auf einmal einstellst, wird vorher nach Menge und Preis gefragt, damit ein versehentlicher Klick nicht einen ganzen Stapel einstellt. Lässt sich ausschalten.",
  ["La AH sin tirones"] = "Kein Ruckeln mehr im AH",
  ["Al acabar un escaneo (el tuyo o el de otro addon, como Auctionator) los precios se guardan poco a poco y el juego ya no se congela. Nueva opción para no leer los escaneos de otros addons."] = "Wenn ein Scan endet (deiner oder der eines anderen Addons wie Auctionator), werden die Preise Stück für Stück gespeichert und das Spiel friert nicht mehr ein. Neue Option, um die Scans anderer Addons nicht zu lesen.",
  ["Rutas sin enfriamientos"] = "Routen ohne Abklingzeiten",
  ["Las transmutaciones y el Mooncloth tienen enfriamiento: la ruta ya no pide 186 transmutaciones seguidas. Como mucho las usa para un punto."] = "Transmutationen und Mondstoff haben Abklingzeiten, daher verlangen Routen keine 186 Transmutationen am Stück mehr. Sie werden höchstens für einen Punkt genutzt.",
  ["Lista de compra en su sitio"] = "Einkaufsliste bleibt an ihrem Platz",
  ["Al cerrar la ventana de vender en la AH, la lista de compra se pega a la AH y no deja un hueco."] = "Schließt du das AH-Verkaufsfenster, rückt die Einkaufsliste jetzt ans AH, statt eine Lücke zu lassen.",

  ["Confirmar antes de anunciar en la AH"] = "Vor dem Einstellen im AH bestätigen",
  ["Al anunciar más de una unidad de golpe (ventana de vender, Inventario, ruta), pregunta antes cuántas y a qué precio. Así un clic sin querer no anuncia un montón."] = "Wenn du mehr als ein Stück auf einmal einstellst (Verkaufsfenster, Inventar, Route), wird vorher nach Menge und Preis gefragt. So stellt ein versehentlicher Klick keinen ganzen Stapel ein.",
  ["Anunciar en la Casa de Subastas"] = "Im Auktionshaus einstellen",
  ["¿Anunciar %d × %s a %s cada uno (%d h)?"] = "%d × %s zu je %s einstellen (%d h)?",
  ["Clic: dejar de mostrar esta ventana, o ver todas las opciones."] = "Klick: dieses Fenster nicht mehr anzeigen oder alle Optionen sehen.",
  ["No mostrar esta ventana"] = "Fenster nicht mehr anzeigen",
  ["Se vuelve a activar en /cj opciones."] = "Du kannst es in /cj options wieder einschalten.",
  ["Todas las opciones"] = "Alle Optionen",
  ["%s: desactivada. Vuelve a activarla en /cj opciones."] = "%s: ausgeschaltet. Schalte es in /cj options wieder ein.",
  ["Esta ventana sale sola al abrir un vendedor. Si no la quieres, quítala en /cj opciones."] = "Dieses Fenster öffnet sich von selbst, wenn du einen Händler ansprichst. Wenn du es nicht willst, schalte es in /cj options aus.",
  ["La lista de compra sale sola al abrir la Casa de Subastas. Si no la quieres, quítala en /cj opciones."] = "Die Einkaufsliste öffnet sich von selbst beim Auktionshaus. Wenn du sie nicht willst, schalte sie in /cj options aus.",
  ["La ventana de vender en la AH sale sola al abrir la Casa de Subastas. Si no la quieres, quítala en /cj opciones."] = "Das Verkaufsfenster öffnet sich von selbst beim Auktionshaus. Wenn du es nicht willst, schalte es in /cj options aus.",
  ["Esta ventana sale sola al abrir una profesión. Si no la quieres, quítala en /cj opciones."] = "Dieses Fenster öffnet sich von selbst, wenn du einen Beruf öffnest. Wenn du es nicht willst, schalte es in /cj options aus.",
  ["Al abrir la AH: una ventana con lo de tus bolsas que se vende mejor en la AH. Clic en una fila para anunciarlo."] = "Beim Öffnen des AH: ein Fenster mit den Gegenständen in deinen Taschen, die sich im AH besser verkaufen. Klicke auf eine Zeile, um sie einzustellen.",

  -- History
  ["un vendedor tiene el %d%% de las subastas"] = "ein Verkäufer hat %d%% der Auktionen",
  ["se pide %dx su precio de vendedor"] = "zum %dx seines Händlerpreises angeboten",

