  -- Market
  [" días"] = " Tage",
  ["de las más baratas no se va ninguna"] = "keine der günstigsten verschwindet",
  ["las más baratas tardan ~"] = "die günstigsten brauchen ~",
  [" en irse"] = " bis sie weg sind",
  ["Estancado: %s (%d de %d seguían en el siguiente escaneo)"] = "Hängt fest: %s (%d von %d waren beim nächsten Scan noch da)",
  ["Estancado: faltan escaneos (bastan 1-2 al día durante un par de días)"] = "Hängt fest: braucht mehr Scans (1-2 pro Tag, ein paar Tage lang)",
  ["Precio clavado: el mínimo lleva %s sin moverse y hay %d subastas en él"] = "Preisboden: das Minimum hat sich seit %s nicht bewegt und %d Auktionen liegen darauf",
  ["Precio clavado: no, el mínimo lleva %s quieto pero hay pocas subastas en él"] = "Preisboden: nein, das Minimum hat sich seit %s nicht bewegt, aber wenige Auktionen liegen darauf",
  ["Precio clavado: no, el mínimo se ha movido en el último día"] = "Preisboden: nein, das Minimum hat sich am letzten Tag bewegt",
  ["Precio clavado: falta historial de al menos medio día"] = "Preisboden: braucht mindestens einen halben Tag Verlauf",
  ["Más oferta: de %d a %d uds a la venta en %s (%+d%%)"] = "Mehr Angebot: von %d auf %d im Angebot in %s (%+d%%)",
  ["Más oferta: falta una foto de hace ~1 día"] = "Mehr Angebot: braucht einen Stand von vor ~1 Tag",
  ["Competencia: %d subastas (%d uds) en el precio mínimo"] = "Konkurrenz: %d Auktionen (%d Stück) zum Mindestpreis",
  ["Competencia: no está en la AH ahora"] = "Konkurrenz: gerade nicht im AH",
  [" (%d de %d señales en contra)"] = " (%d von %d Warnzeichen)",
  ["Las más baratas no se venden: aunque el margen parezca bueno, probablemente no lo venderás."] = "Die günstigsten verkaufen sich nicht: auch wenn die Marge gut aussieht, wirst du es wohl nicht verkaufen.",
  ["Precio clavado y cada vez más oferta: aunque el margen parezca bueno, probablemente no lo venderás."] = "Preisboden und wachsendes Angebot: auch wenn die Marge gut aussieht, wirst du es wohl nicht verkaufen.",

  -- ProfessionUI
  ["objeto "] = "Gegenstand ",
  ["no quedan suficientes en la AH de: "] = "nicht genug übrig im AH von: ",
  ["%d materiales sin precio (no están en la AH)"] = "%d Materialien ohne Preis (nicht im AH)",
  ["%d materiales sin precio: aún no tienes escaneo de la Casa de Subastas. Ábrela y pulsa Escanear"] = "%d Materialien ohne Preis: du hast noch keinen Scan des Auktionshauses. Öffne es und klicke auf Scannen",
  ["Casa de Subastas neutral: Crafter's Journal no le da soporte. Aquí no escanea ni abre sus ventanas; sus rutas y precios siguen siendo los de la Casa de Subastas de tu facción."] = "Neutrales Auktionshaus: Crafter's Journal unterstützt es nicht. Es scannt hier nicht und öffnet seine Fenster nicht; seine Routen und Preise bleiben beim Auktionshaus deiner Fraktion.",
  ["no hay más recetas de instructor para ese nivel"] = "keine weiteren Lehrerrezepte für diese Stufe",
  ["lo que sigue se aprende de pergaminos que no vende ningún vendedor ni están en la AH: %s"] = "das Nächste lernt man aus Rezepten, die kein Händler verkauft und die nicht im AH sind: %s",
  ["lo que sigue pide más reputación: %s"] = "das Nächste erfordert mehr Ruf: %s",
  ["lo que sigue es de una especialización que no tienes: %s"] = "das Nächste gehört zu einer Spezialisierung, die du nicht hast: %s",
  ["lo que sigue se compra con Merchant's Favor (actívalo con su icono): %s"] = "das Nächste kauft man mit Merchant's Favor (über sein Symbol einschalten): %s",
  ["Amarilla desde %d · verde desde %d · gris desde %d"] = "Gelb ab %d · grün ab %d · grau ab %d",
  ["Hay recetas con más probabilidad, pero falta el precio de algún material en la AH:"] = "Es gibt Rezepte mit besseren Chancen, aber einem Material fehlt der AH-Preis:",
  [": falta "] = ": fehlt ",
  ["Si consigues esos materiales (o aparecen en la AH), el plan las usará."] = "Bekommst du diese Materialien (oder tauchen sie im AH auf), nutzt der Plan sie.",
  ["No hay ninguna receta de instructor mejor en este tramo: esta es la única opción."] = "In diesem Bereich gibt es kein besseres Lehrerrezept: das ist die einzige Option.",
  ["Materiales de este paso:"] = "Materialien für diesen Schritt:",
  ["Probabilidad de subir: del %d%% al %d%%"] = "Chance auf einen Punkt: von %d%% bis %d%%",
  ["fabricarlo (%s): %s/u · comprarlo hecho: %s/u"] = "selbst herstellen (%s): %s/Stk · fertig kaufen: %s/Stk",
  ["comprado: %s/u · fabricarlo (%s): %s/u"] = "gekauft: %s/Stk · selbst herstellen (%s): %s/Stk",
  ["fabricarlo quitaría puntos a %s"] = "selbst herstellen würde %s Punkte wegnehmen",
  ["Guarda %d para pasos posteriores."] = "Behalte %d für spätere Schritte.",
  ["Vendido al vendedor recuperas %s por fabricación."] = "Beim Händler bekommst du %s pro Herstellung zurück.",
  ["Lenta: %s por fabricación."] = "Langsam: %s pro Herstellung.",
  ["Si prefieres otra receta, quítala con la X (o activa \"Menos fabricaciones\", que evita las lentas)."] = "Wenn du lieber ein anderes Rezept willst, entferne es mit dem X (oder aktiviere \"Weniger Herstellungen\", das langsame vermeidet).",
  ["Si lo vendes en la AH podrías sacar hasta %s más en este paso, pero no se sabe cuántos se venden."] = "Im AH zu verkaufen könnte in diesem Schritt bis zu %s mehr bringen, aber niemand weiß, wie viele sich verkaufen.",
  ["Precio poco fiable: "] = "Unzuverlässiger Preis: ",
  ["Fabricas %d en total en el plan."] = "Du stellst im Plan insgesamt %d her.",
  ["Guarda %d (no los vendas):"] = "Behalte %d (nicht verkaufen):",
  [" (paso %d-%d)"] = " (Schritt %d-%d)",
  ["  %dx para %s%s"] = "  %dx für %s%s",
  ["Te sobran %d. El plan cuenta venderlos al vendedor a %s cada uno."] = "%d bleiben übrig. Der Plan zählt ihren Verkauf an den Händler zu je %s.",
  ["En la AH te quedarían %s cada uno igualando a la más barata (subasta de 24 h, comisión y depósito de %s descontados): hasta %s más en total."] = "Im AH bekämst du je %s zum günstigsten Preis (24-h-Auktion, Gebühr und %s Anzahlung abgezogen): insgesamt bis zu %s mehr.",
  ["Pero el juego no dice cuántos se venden: puede que no los vendas todos, o ninguno. Anuncia unos pocos y mira las alertas:"] = "Aber das Spiel verrät nicht, wie viele sich verkaufen: vielleicht nicht alle oder keine. Stelle ein paar ein und achte auf die Hinweise:",
  ["Consejo: pon los %d en la AH a %s (1 cobre menos que la más barata)."] = "Tipp: stelle alle %d im AH zu %s ein (1 Kupfer unter dem günstigsten).",
  ["Consejo: pon solo %d en la AH a %s para probar y vende el resto al vendedor; si se venden, anuncia más."] = "Tipp: stelle nur %d im AH zu %s zum Testen ein und verkaufe den Rest an den Händler; verkaufen sie sich, stelle mehr ein.",
  ["Consejo: con estas alertas, mejor véndelos al vendedor."] = "Tipp: mit diesen Hinweisen besser an den Händler verkaufen.",
  ["Consejo: véndelos al vendedor; en la AH no compensa la diferencia."] = "Tipp: verkaufe sie an den Händler; der AH-Unterschied lohnt sich nicht.",
  ["%d uds a %s de media, comprando de la más barata a la más cara (ahora hay %d a la venta)."] = "%d zu durchschnittlich %s, vom günstigsten zum teuersten gekauft (%d gerade im Angebot).",
  ["Hacen falta más de las que hay: las %d que faltan se cuentan al precio típico (mediana)."] = "Du brauchst mehr, als es gibt: die fehlenden %d zählen zum üblichen Preis (Median).",
  ["Vendedor más cercano"] = "Nächster Händler",
  ["Pulsa para cambiarlo."] = "Klicken zum Ändern.",
  ["Usar lo que tienes en bolsas"] = "Was in deinen Taschen ist, nutzen",
  ["La ruta usa primero tus materiales y solo compra lo que falta."] = "Die Route nutzt zuerst deine Materialien und kauft nur, was fehlt.",
  ["La ruta compra todo, aunque lo tengas."] = "Die Route kauft alles, auch was du schon hast.",
  ["Recetas de misiones"] = "Questrezepte",
  ["Si una misión de tu bando da la receta, no cuesta oro. Lo que pida entregar no tiene precio: se ve en el tooltip de la receta."] = "Gibt eine Quest deiner Fraktion das Rezept, kostet es kein Gold. Was sie zur Abgabe verlangt, hat keinen Preis: siehe den Tooltip des Rezepts.",
  ["Las recetas solo se consiguen comprándolas (vendedor o Casa de Subastas)."] = "Rezepte gibt es nur durch Kauf (Händler oder Auktionshaus).",
  ["Ventas al vendedor"] = "Händlerverkäufe",
  ["Lo que sacas vendiendo al vendedor todo lo que fabricas y no guardas para pasos siguientes. La ruta cuenta este precio porque es una venta segura."] = "Was du bekommst, wenn du alles Hergestellte, das du nicht für spätere Schritte behältst, an einen Händler verkaufst. Die Route rechnet mit diesem Preis, weil der Verkauf sicher ist.",
  ["En la vista %s verás qué conviene poner en la AH: hasta %s más, sin garantía de venta."] = "Die Ansicht %s zeigt, was sich im AH lohnt: bis zu %s mehr, ohne Verkaufsgarantie.",
  ["En la vista %s verás qué hacer con cada cosa que fabricas."] = "Die Ansicht %s zeigt, was du mit jedem Hergestellten machen solltest.",
