  ["la ruta no se podría seguir en orden"] = "die Route ließe sich nicht der Reihe nach befolgen",
  ["la ruta también cuenta fabricaciones, pasos y lo de tus bolsas"] = "die Route berücksichtigt auch Herstellungen, Schritte und deine Taschen",
  ["Comparando con otras recetas…"] = "Vergleiche mit anderen Rezepten…",
  ["Por qué esta y no otra:"] = "Warum dieses und kein anderes:",
  ["%d fabricaciones (aquí %d) · %s/u (aquí %s) · recuperas %s/u (aquí %s)"] = "%d Herstellungen (hier %d) · %s/Stk. (hier %s) · Rückverkauf %s/Stk. (hier %s)",
  ["aprender"] = "erlernen",
  ["Peor porque: "] = "Schlechter, weil: ",
  ["Vendiendo lo fabricado en la AH saldría %s mejor que la ruta, si se vende (la ruta cuenta el vendedor, que es lo seguro)."] = "Das Hergestellte im AH zu verkaufen brächte %s mehr als die Route, falls es sich verkauft (die Route rechnet mit dem Händler, das ist sicher).",
  -- Calculadora
  ["Calculadora"] = "Rechner",
  ["Cuánto ganas con una receta, como en una hoja de cálculo: guarda varios cálculos y escribe tus precios."] = "Wie viel dir ein Rezept bringt, wie eine Tabelle: speichere mehrere Berechnungen und gib eigene Preise ein.",
  ["Cuánto ganas con una receta: materiales en crudo, venta, comisión y depósito. Escribe tus precios si la AH ha cambiado."] = "Wie viel dir ein Rezept bringt: Rohmaterialien, Verkauf, AH-Gebühr und Anzahlung. Gib eigene Preise ein, wenn sich das AH geändert hat.",
  ["Receta desconocida"] = "Unbekanntes Rezept",
  ["a mano"] = "eingegeben",
  ["vendedor"] = "Händler",
  ["Subasta de %d h"] = "%d-h-Auktion",
  ["Depósito: el %d%% del precio de vendedor, mínimo %s por subasta. Se devuelve si se vende; lo pierdes si caduca o la cancelas."] = "Anzahlung: %d%% des Händlerpreises, mindestens %s pro Auktion. Erstattet bei Verkauf; verloren, wenn sie abläuft oder du sie abbrichst.",
  ["sin precio"] = "kein Preis",
