  ["Borra los precios que has escrito en este cálculo y vuelve a los del último escaneo y el vendedor."] = "Löscht die Preise, die du in dieser Berechnung eingegeben hast, und kehrt zu den Preisen des letzten Scans und der Händler zurück.",
  ["Aún no tienes cálculos. Busca una receta arriba a la derecha para añadir el primero."] = "Du hast noch keine Berechnungen. Suche oben rechts ein Rezept, um die erste hinzuzufügen.",
  ["no la sabes"] = "du kennst es nicht",
  ["Venta: %s × %s"] = "Verkauf: %s × %s",
  ["No fabrica un objeto que se pueda vender (encantamiento)."] = "Es stellt keinen verkaufbaren Gegenstand her (Verzauberung).",
  ["Comisión de la AH (%d%%)"] = "AH-Gebühr (%d%%)",
  ["Chat de comercio"] = "Handelschat",
  ["Vender por el chat de comercio"] = "Über den Handelschat verkaufen",
  ["Al precio que paga el vendedor: venta segura, sin comisión ni depósito."] = "Zu dem Preis, den der Händler zahlt: ein sicherer Verkauf, ohne Gebühr oder Anzahlung.",
  ["Beneficio vendiendo al vendedor (sin AH)"] = "Gewinn beim Verkauf an den Händler (ohne AH)",
  ["Otro addon acaba de pedir un escaneo completo: el servidor no permitirá otro hasta dentro de %s."] = "Ein anderes Addon hat gerade einen vollständigen Scan angefordert: der Server erlaubt den nächsten erst in %s.",
  ["Algún material no tiene precio (ni en el escaneo ni en el vendedor): escríbelo para que cuente."] = "Ein Material hat keinen Preis (weder im Scan noch beim Händler): gib ihn ein, damit er zählt.",
  ["Precios de vendedor con el descuento de tu reputación con %s (-%d%%)."] = "Händlerpreise mit deinem Rufrabatt bei %s (-%d%%).",
  ["No salía en el último escaneo de la AH: no se sabe si allí vale más. Escanea la AH para compararlo."] = "Es war nicht im letzten AH-Scan, daher ist unklar, ob es dort mehr wert ist. Scanne das AH zum Vergleichen.",
  ["+%d%% sobre su precio habitual"] = "+%d%% über seinem üblichen Preis",
  ["Ha subido (los últimos días, ~%s), pero según TSM en la región se vende a ~%s: se cuenta al precio de ahora."] = "Es ist gestiegen (in den letzten Tagen ~%s), aber laut TSM verkauft es sich in der Region für ~%s: es zählt der aktuelle Preis.",
  ["Ha subido de golpe y puede que no se venda a este precio: se prueba con %d. Si caduca solo pierdes el depósito y lo sigues pudiendo vender al vendedor (%s)."] = "Der Preis ist plötzlich gestiegen und es verkauft sich zu diesem Preis vielleicht nicht: Versuch mit %d. Läuft es ab, verlierst du nur die Anzahlung und kannst es weiterhin an den Händler verkaufen (%s).",
  ["Sacarías vendiéndolo"] = "Beim Verkauf bekämst du",
  ["En la Casa de Subastas"] = "Im Auktionshaus",
  ["Al vendedor"] = "An den Händler",
  ["Han subido de precio"] = "Im Preis gestiegen",
  ["Qué vender de tus bolsas, dónde y cuánto sacas. Lo que necesitan tus rutas empezadas se guarda."] = "Was du aus deinen Taschen verkaufst, wo und wie viel du bekommst. Was deine begonnenen Routen brauchen, wird behalten.",
  ["Vendidos %d objetos al vendedor."] = "%d Gegenstände an den Händler verkauft.",
  ["Vende al vendedor todo lo que va al vendedor (no lo que va a la AH ni lo que guardan tus rutas)."] = "Verkauft alles an den Händler, was an den Händler geht (nicht was ins AH geht oder deine Routen behalten).",
  ["Sin escaneo de la AH: al vendedor solo se propone lo gris. Escanea para ver qué vale más en la AH.|r"] = "Kein AH-Scan: nur graue Gegenstände werden zum Händlerverkauf vorgeschlagen. Scanne, um zu sehen, was im AH mehr wert ist.|r",
  ["Precios de la AH de hace %d h: escanea antes de anunciar.|r"] = "AH-Preise von vor %d h: scanne vor dem Einstellen.|r",
  ["Precios de la AH de hace %d min · neto tras la comisión|r"] = "AH-Preise von vor %d Min. · netto nach Gebühr|r",
  ["(lo que te queda tras la comisión de la AH; el depósito se devuelve al venderse)"] = "(was dir nach der AH-Gebühr bleibt; die Anzahlung kommt bei Verkauf zurück)",
  ["Ha subido: véndelo ahora"] = "Gestiegen: jetzt verkaufen",
  ["Vender en la Casa de Subastas"] = "Im Auktionshaus verkaufen",
  ["Guardar para tus rutas"] = "Für deine Routen behalten",
  ["No llevas nada que se pueda vender."] = "Du hast nichts dabei, was sich verkaufen lässt.",

  -- Earn: minimum profit
  ["Beneficio mínimo"] = "Mindestgewinn",
  ["No se proponen recetas que, con todas las fabricaciones que tocan, dejen menos que esto (tampoco materiales para vender que valgan menos)."] = "Rezepte, die über alle vorgeschlagenen Herstellungen weniger bringen, werden nicht vorgeschlagen (ebenso wenig Materialien zum Verkauf, die weniger wert sind).",
  ["Arrastra o usa la rueda del ratón."] = "Ziehe es oder nutze das Mausrad.",
  ["Recetas que podrías aprender"] = "Rezepte, die du erlernen könntest",
  ["%s: no se propondrá venderlo. Se deshace con clic derecho en \"No se venden\" (pestaña Inventario)."] = "%s: wird nicht mehr zum Verkauf angeboten. Rückgängig per Rechtsklick in \"Nicht verkaufen\" (Reiter Inventar).",
  ["%s: vuelve a proponerse para vender."] = "%s: wird wieder zum Verkauf angeboten.",
  ["herramienta de profesión: no se vende"] = "Berufswerkzeug: wird nicht verkauft",
  ["lo marcaste para no venderlo"] = "du hast es als nicht zu verkaufen markiert",
  ["clic derecho: volver a proponerlo"] = "Rechtsklick: wieder anbieten",
  ["No se venden"] = "Nicht verkaufen",
  ["Herramienta de profesión: sin ella no puedes fabricar o recolectar. No se propone venderla."] = "Berufswerkzeug: ohne es kannst du nicht herstellen oder sammeln, daher wird es nicht zum Verkauf angeboten.",
  ["Lo marcaste para no venderlo."] = "Du hast es als nicht zu verkaufen markiert.",
  ["Clic derecho: volver a proponerlo para vender."] = "Rechtsklick: wieder zum Verkauf anbieten.",
  ["Clic derecho: no venderlo nunca."] = "Rechtsklick: nie verkaufen.",
