  ["Clic derecho: no venderlo nunca · Ctrl+clic derecho: al vendedor."] = "Rechtsklick: nie verkaufen · Strg+Rechtsklick: an den Händler.",
  ["Ctrl+clic derecho: venderlo al vendedor."] = "Strg+Rechtsklick: an den Händler verkaufen.",
  ["Ctrl+clic derecho: volver a compararlo con la AH."] = "Strg+Rechtsklick: wieder mit dem AH vergleichen.",
