  ["lo pasaste a la AH"] = "von dir dem AH zugewiesen",
  ["Ctrl+clic derecho: anunciarlo en la AH (arriesgando el depósito)."] = "Strg+Rechtsklick: im AH einstellen (Anzahlung riskieren).",
  ["%s: se propondrá anunciarlo en la AH. Ctrl+clic derecho en su fila lo devuelve al vendedor."] = "%s: wird zum Einstellen im AH vorgeschlagen. Strg+Rechtsklick auf die Zeile schickt es zurück zum Händler.",
  ["%s: se propondrá venderlo al vendedor. Ctrl+clic derecho en su fila lo devuelve a la AH."] = "%s: wird zum Verkauf an den Händler vorgeschlagen. Strg+Rechtsklick auf die Zeile schickt es zurück ins AH.",
  ["%s: vuelve a compararse con la AH."] = "%s: wird wieder mit dem AH verglichen.",
  ["Para vender en la AH, de tus bolsas:"] = "Im AH verkaufen, aus deinen Taschen:",
  ["Anuncias %d × %s · %d h"] = "Du stellst %d × %s ein · %d h",
  ["La Casa de Subastas no aceptó %s: %s"] = "Das Auktionshaus hat %s nicht angenommen: %s",
