  ["lo que sobra · ~%s puntos"] = "Reste · ~%s Punkte",
  ["Te han sobrado materiales de un paso ya hecho y esta receta aún da puntos. Gastarlos deja más que venderlos: los puntos que te da ya no los subes con la receta siguiente."] = "Von einem erledigten Schritt sind Materialien übrig und dieses Rezept gibt noch Punkte. Sie zu verbrauchen bringt mehr als sie zu verkaufen: Die Punkte, die es dir gibt, brauchst du mit dem nächsten Rezept nicht mehr.",
  ["Puntos que te ahorras"] = "Gesparte Punkte",
  ["Lo que vale lo fabricado"] = "Wert des Hergestellten",
  ["Materiales (venderlos o reponerlos)"] = "Materialien (verkaufen oder ersetzen)",
  ["Ganas"] = "Du gewinnst",
  ["Solo cuenta lo que no pide el resto de la ruta. Si prefieres venderlo, Saltar lo quita."] = "Es zählt nur, was der Rest der Route nicht braucht. Wenn du lieber verkaufst, entfernt Überspringen es.",
  ["Clic: abrir la receta y fabricar %d."] = "Klick: Rezept öffnen und %d herstellen.",
  ["La Casa de Subastas no confirmó el anuncio de %s: míralo en Subastas."] = "Das Auktionshaus hat die Auktion von %s nicht bestätigt: sieh unter Auktionen nach.",
  ["No compensa venderlo ahora"] = "Lohnt sich gerade nicht zu verkaufen",
  ["Lista de compra:"] = "Einkaufsliste:",
  ["Tu ruta ya usa tu último escaneo de la AH (de hace %d min). Cuando escanees otra vez, aquí aplicas los precios nuevos."] = "Deine Route nutzt bereits deinen letzten AH-Scan (vor %d Min.). Nach deinem nächsten Scan übernimmst du die neuen Preise hier.",
  ["Tu ruta ya usa tu último escaneo de la AH. Cuando escanees otra vez, aquí aplicas los precios nuevos."] = "Deine Route nutzt bereits deinen letzten AH-Scan. Nach deinem nächsten Scan übernimmst du die neuen Preise hier.",
  ["Working Overtime +%d%%"] = "Working Overtime +%d%%",
  ["Talento de legado, rango %d/5: +%d%% de probabilidad de subir punto en las recetas amarillas y verdes."] = "Vermächtnistalent, Rang %d/5: +%d%% Punktchance bei gelben und grünen Rezepten.",
  ["Las rutas lo cuentan: piden menos fabricaciones en los pasos amarillos y verdes."] = "Routen berücksichtigen es: sie verlangen weniger Herstellungen bei gelben und grünen Schritten.",
  ["Las rutas aún no lo cuentan: no se sabe con certeza cómo lo aplica el juego. Con él necesitarás algo menos de fabricaciones de las que dice la ruta en los pasos amarillos y verdes."] = "Routen berücksichtigen es noch nicht: es ist nicht bestätigt, wie das Spiel es anwendet. Damit brauchst du bei gelben und grünen Schritten etwas weniger Herstellungen, als die Route sagt.",
  ["Por eso compensa comprar por tramos (lo que hace la Lista de compra por defecto): cada tramo compra solo lo suyo y el siguiente cuenta lo que te sobró, así que como mucho te sobra algo de un tramo."] = "Deshalb lohnt sich der Kauf nach Abschnitten (die Einkaufsliste macht es standardmäßig): jeder Abschnitt kauft nur, was er braucht, und der nächste zählt, was dir übrig bleibt, sodass höchstens ein paar Materialien eines Abschnitts übrig bleiben.",
  ["Hasta aquí: unos %d min de fabricar. Más fabricaciones aún darían beneficio, pero no compensa el tiempo."] = "Endet hier: etwa %d Min. Herstellen. Mehr Herstellungen würden sich noch lohnen, aber nicht die Zeit.",
  ["AH: te quedarían %s, pero si caduca pierdes %s de depósito · el vendedor no lo compra"] = "AH: du bekämst %s, verlierst aber %s Anzahlung, wenn es abläuft · Händler kaufen es nicht",
