  ["esta tanda: %d"] = "diese Charge: %d",
  ["sin materiales: sigue con el paso, se compran en la siguiente tanda"] = "keine Materialien: mach mit dem Schritt weiter, sie werden mit der nächsten Charge gekauft",
  ["Lo que llevas da para %d de las ~%d fabricaciones del paso. Con suerte te basta; si no, al acabarlo la ruta te llevará a comprar más."] = "Was du dabeihast, reicht für %d der ~%d Herstellungen des Schritts. Mit Glück genügt es; sonst schickt dich die Route, wenn es aufgebraucht ist, mehr kaufen.",
  -- Kauf-Zeilen der Route (ProfessionUI.lua, AddBuyLines)
  ["Compra %d× %s"] = "Kaufe %d× %s",
  ["Compra en la AH: %d materiales"] = "Im AH kaufen: %d Materialien",
  ["Compra al vendedor: %d materiales"] = "Beim Händler kaufen: %d Materialien",
  ["en la AH"] = "im AH",
  ["en el vendedor"] = "beim Händler",
  ["No había suficiente"] = "Es gab nicht genug",
  ["comprar a este vendedor justo lo que falta"] = "bei diesem Händler genau das Fehlende kaufen",
  ["volver a añadirla a la Lista de compra y marcar el camino"] = "wieder zur Einkaufsliste hinzufügen und den Weg markieren",
  ["No está en tu Lista de compra · clic para añadirla"] = "Nicht auf deiner Einkaufsliste · Klick fügt sie hinzu",
  -- Novedades 0.58.0 (WhatsNew.lua)
  ["Opciones en su propia ventana"] = "Optionen im eigenen Fenster",
  ["El engranaje junto al idioma abre las opciones, ordenadas por categorías: General y una por pestaña o ventana. Ya no están en el panel de AddOns del juego."] = "Das Zahnrad neben der Sprachauswahl öffnet die Optionen, nach Kategorien sortiert: Allgemein und eine pro Reiter oder Fenster. Sie sind nicht mehr im AddOn-Bereich des Spiels.",
  ["Al vendedor, solo lo que no vale más en la AH"] = "Zum Händler nur, was im AH nicht mehr wert ist",
  ["Inventario y la ventana del vendedor ya no te proponen vender al vendedor lo que vale más en la AH. Si tu escaneo no tiene un objeto, se usa el precio de Auctionator o TSM."] = "Inventar und das Händlerfenster schlagen nicht mehr vor, beim Händler zu verkaufen, was im AH mehr wert ist. Fehlt ein Gegenstand in deinem Scan, wird der Preis von Auctionator oder TSM genutzt.",
  ["En el tope de tu rango, a entrenar"] = "Am Rang-Maximum: trainieren",
  ["Si llegas al tope de tu rango sin el siguiente, el paso actual de la ruta pasa a ser entrenarlo, en vez de fabricar algo que ya no sube puntos."] = "Erreichst du das Maximum deines Rangs ohne den nächsten, wird der aktuelle Schritt der Route, ihn zu trainieren, statt etwas herzustellen, das keine Punkte mehr gibt.",
  ["La ruta explica su segunda receta"] = "Die Route erklärt ihr zweites Rezept",
  ["Si hay otra receta más barata en oro y la ruta no la usa, el paso dice por qué: más fabricaciones, un paso más o aprenderla no compensa."] = "Ist ein anderes Rezept in Gold günstiger und die Route nutzt es nicht, sagt der Schritt warum: mehr Herstellungen, ein Schritt mehr oder das Erlernen lohnt nicht.",
  ["Ya fuiste y no lo compraste todo: mientras puedas fabricar, la ruta sigue. Si no hay de dónde sacarlo, quita esa receta desde la ventana del addon."] = "Du warst schon dort und hast nicht alles gekauft: solange du noch herstellen kannst, geht die Route weiter. Gibt es keine Quelle, entferne dieses Rezept im Addon-Fenster.",
  ["Stock limitado: venden pocas y reponen con el tiempo, y a veces otros jugadores las compran para revenderlas."] = "Begrenzter Vorrat: Sie verkaufen wenige und füllen mit der Zeit auf, und manchmal kaufen andere Spieler sie zum Weiterverkauf.",
  ["Sale mejor que la de la ruta."] = "Es ist besser als das der Route.",
  ["Asistente de la ruta"] = "Routen-Assistent",
  ["Sigue esta ruta paso a paso en un banner pequeño, sin la ventana del addon: qué toca, dónde ir y qué comprar. Clic otra vez para cerrarlo."] = "Folge dieser Route Schritt für Schritt in einem kleinen Banner, ohne das Addon-Fenster: was ansteht, wohin du gehst und was du kaufst. Erneut klicken zum Schließen.",
  ["Aprende %s"] = "Lerne %s",
  ["Aún no la tienes: apréndela en su instructor (Aprendiz, gratis o casi). Sube el tope a 75."] = "Du hast ihn noch nicht: lerne ihn bei seinem Lehrer (Lehrling, kostenlos oder fast). Das hebt das Maximum auf 75.",
  ["Solo puedes tener dos profesiones principales (las de recolección también cuentan): si ya tienes dos, tendrías que olvidar una."] = "Du kannst nur zwei Hauptberufe haben (Sammelberufe zählen mit): hast du schon zwei, müsstest du einen verlernen.",
  ["Instructor · aún no la tienes"] = "Lehrer · du hast ihn noch nicht",
  ["Sube el tope a %d%s"] = "Hebt das Maximum auf %d%s",
  -- Flecha GPS del asistente (Assistant.lua)
  ["%d yd"] = "%d yd",
  ["En otro continente"] = "Auf einem anderen Kontinent",
  ["Sin posición aquí"] = "Hier keine Position",
  -- Banco del asistente (ProfessionUI.lua AddBuyLines, Assistant.lua)
  ["Saca %d× %s del banco"] = "Nimm %d× %s aus der Bank",
  ["Ve al banco: %d materiales"] = "Zur Bank: %d Materialien",
  ["en el banco"] = "in der Bank",
  ["sacar a tus bolsas lo que falta"] = "das Fehlende in deine Taschen holen",
  ["Banquero más cercano"] = "Nächster Bankier",
  ["Sacar del banco"] = "Aus der Bank holen",
  ["saca %d (tienes %d en el banco)"] = "%d holen (%d in der Bank)",
  ["Según lo que había la última vez que abriste el banco."] = "Nach dem Stand beim letzten Öffnen der Bank.",
  ["No cabe todo en tus bolsas: faltan %d por sacar del banco."] = "Nicht alles passt in deine Taschen: noch %d aus der Bank zu holen.",
  [" o "] = " oder ",
  ["Está en %s"] = "Es ist in %s",
  ["Barco en %s"] = "Schiff in %s",
  ["Zepelín en %s"] = "Zeppelin in %s",
  ["Asistente de ruta"] = "Routen-Assistent",
  ["Sacar el asistente al empezar una ruta"] = "Assistent beim Beginnen einer Route zeigen",
  ["Al empezar una ruta sale solo el asistente con ella. Desactivado, solo sale cuando lo abres: botón del catalejo junto a Dejar ruta, o /cj mini."] = "Beginnst du eine Route, erscheint der Assistent von selbst. Aus: nur wenn du ihn öffnest (Fernrohr neben Route verlassen, oder /cj mini).",
  ["Bloquear el asistente"] = "Assistent sperren",
  ["No se mueve al arrastrarlo."] = "Er bewegt sich beim Ziehen nicht.",
  ["Mostrar la flecha GPS"] = "GPS-Pfeil zeigen",
  -- Confirmar antes de las acciones de golpe y novedades (UI.lua ES:Confirm, WhatsNew.lua)
  ["Ya no se mostrará este aviso. Se vuelve a activar en /cj opciones (%s)."] = "Dieser Hinweis erscheint nicht mehr. Wieder einschalten in /cj Optionen (%s).",
  ["No volver a mostrar este aviso"] = "Diesen Hinweis nicht mehr zeigen",
  ["Se vuelve a activar en /cj opciones (%s)."] = "Wieder einschalten in /cj Optionen (%s).",
  ["Sí"] = "Ja",
  ["No"] = "Nein",
  ["Comprar todo"] = "Alles kaufen",
  ["¿Comprar %d materiales de la lista de compra por %s?"] = "%d Materialien der Einkaufsliste für %s kaufen?",
  ["¿Vender %d objetos al vendedor por %s?"] = "%d Gegenstände für %s an den Händler verkaufen?",
  ["Confirmar antes de Vender todo"] = "Vor Alles verkaufen bestätigen",
  ["Al pulsar Vender todo en la ventana junto al vendedor, pregunta antes qué vende y por cuánto."] = "Beim Klick auf Alles verkaufen im Fenster neben dem Händler wird vorher gefragt, was und für wie viel verkauft wird.",
  ["Confirmar antes de Comprar todo"] = "Vor Alles kaufen bestätigen",
  ["Al pulsar Comprar todo en la ventana junto al vendedor, pregunta antes cuántos materiales compra y por cuánto."] = "Beim Klick auf Alles kaufen im Fenster neben dem Händler wird vorher gefragt, wie viele Materialien und für wie viel gekauft werden.",
  ["Confirmar antes de vender todo al vendedor"] = "Vor dem Verkauf von allem an den Händler bestätigen",
  ["Al pulsar el botón de vender al vendedor de la pestaña Inventario, pregunta antes cuántos objetos vende y por cuánto."] = "Beim Klick auf den Verkaufen-Knopf im Reiter Inventar wird vorher gefragt, wie viele Gegenstände und für wie viel verkauft werden.",
  ["Mostrar las novedades al actualizar"] = "Neuigkeiten nach einem Update zeigen",
  ["Tras actualizar el addon, una ventana con lo nuevo de esa versión (una vez por versión). También se quita con su casilla \"No volver a mostrar\"."] = "Nach einem Addon-Update ein Fenster mit den Neuigkeiten dieser Version (einmal pro Version). Auch mit dem Kästchen \"Nicht mehr zeigen\" abschaltbar.",
  ["Ya no se mostrarán las novedades. Se vuelven a activar en /cj opciones (General)."] = "Neuigkeiten werden nicht mehr gezeigt. Wieder einschalten in /cj Optionen (Allgemein).",
  ["No volver a mostrar"] = "Nicht mehr zeigen",
  ["Clic: seleccionarlo y marcarlo con una estrella (si está cerca)."] = "Klick: ins Ziel nehmen und mit einem Stern markieren (wenn in der Nähe).",
  ["Controles siempre visibles"] = "Steuerelemente immer sichtbar",
  ["Activado, los controles alrededor del asistente (flechas de pasos, modo de compra, saltar, cerrar) se ven siempre. Desactivado, se despliegan al pasar el ratón por el asistente y se pliegan al salir."] = "An: Die Steuerelemente um den Assistenten (Schritt-Pfeile, Kaufmodus, Überspringen, Schließen) sind immer zu sehen. Aus: Sie klappen beim Überfahren des Assistenten aus und beim Verlassen wieder ein.",
  ["Clic para marcarlo"] = "Klick zum Markieren",
  ["Encima del asistente, una flecha que te lleva al instructor o al vendedor del paso, con las yardas y el tiempo. Al pulsar el banner se marca además el camino como en la ventana del addon."] = "Über dem Assistenten ein Pfeil zum Lehrer oder Händler des Schritts, mit Yards und Zeit. Ein Klick auf das Banner markiert außerdem den Weg wie im Addon-Fenster.",
  ["Saltar"] = "Überspringen",
  ["ruta entera"] = "ganze Route",
  ["ya puedes · antes de %d"] = "jetzt möglich · vor %d",
  ["aprende también: %s"] = "lerne auch: %s",
  ["Receta comprada: "] = "Rezept gekauft: ",
  ["Buzón"] = "Briefkasten",
  ["+%d después"] = "+%d später",
  ["Guarda las otras %d: no se sabe si se venden bien, así que anuncia unas pocas y, cuando se vendan, las siguientes (aunque sea en varios días). En la AH valen más que en el vendedor."] = "Behalte die anderen %d: Es ist unklar, ob sie sich gut verkaufen. Stelle ein paar ein und, wenn sie verkauft sind, die nächsten (auch über mehrere Tage). Im AH sind sie mehr wert als beim Händler.",
  ["Siguiendo el consejo (AH y vendedor)"] = "Mit der Empfehlung (AH und Händler)",
  ["Lo del vendedor es seguro; lo de la AH, si se vende"] = "Der Händleranteil ist sicher; der AH-Anteil, falls er verkauft wird",
  ["con AH: "] = "mit AH: ",
  ["Vendiendo al vendedor (seguro)"] = "Verkauf an den Händler (sicher)",
  ["El segundo total cuenta lo que la vista %s aconseja anunciar en la AH a su precio actual. No es seguro: depende de que se venda, a ese precio y antes de que caduque la subasta. Lo del vendedor sí es seguro."] = "Die zweite Summe zählt, was die Ansicht %s im AH einzustellen empfiehlt, zum aktuellen Preis. Das ist nicht garantiert: Es muss sich zu diesem Preis verkaufen, bevor die Auktion abläuft. Der Händleranteil ist sicher.",
  ["Para seguir fabricando, compra más"] = "Um weiter herzustellen, kaufe mehr",
  ["Clic: aprenderlo en este instructor."] = "Klick: bei diesem Lehrer lernen.",
  ["Este instructor no lo enseña (o aún no te llega el nivel)."] = "Dieser Lehrer bringt es nicht bei (oder deine Stufe reicht noch nicht).",
  ["Buzón más cercano"] = "Nächster Briefkasten",
  ["Recoge el correo"] = "Post abholen",
  ["Lo comprado en la AH: "] = "Im AH gekauft: ",
  ["%d objetos comprados en la AH"] = "%d im AH gekaufte Gegenstände",
  ["Lo que compraste en la AH para esta ruta. Este paso se da por hecho cuando lo tienes en las bolsas."] = "Was du für diese Route im AH gekauft hast. Dieser Schritt ist erledigt, sobald es in deinen Taschen ist.",
  ["Comprada en la AH · apréndela antes de fabricar"] = "Im AH gekauft · vor dem Herstellen lernen",
  ["aprende %s primero"] = "zuerst %s lernen",
  ["Compra detectada: %s ×%d. Cuenta ya para la ruta y la lista de compra."] = "Kauf erkannt: %s ×%d. Zählt schon für die Route und die Einkaufsliste.",
  ["compra también la receta: %s"] = "kaufe auch das Rezept: %s",
  ["fabrica aquí hasta %s"] = "hier bis %s herstellen",
  ["Los pasos de compra y la Lista de compra piden solo lo del tramo en el que estás."] = "Die Kaufschritte und die Einkaufsliste verlangen nur den aktuellen Abschnitt.",
  ["Los pasos de compra y la Lista de compra piden lo que falta para toda la ruta, de una vez."] = "Die Kaufschritte und die Einkaufsliste verlangen alles, was für die ganze Route fehlt, auf einmal.",
  ["Es el modo de ahora."] = "Das ist der aktuelle Modus.",
  ["Clic: cambiar a este modo."] = "Klick: zu diesem Modus wechseln.",
  ["Cómo funciona el asistente"] = "So funktioniert der Assistent",
  ["Abrir la ruta en la ventana"] = "Route im Fenster öffnen",
  ["La ruta entera, en el paso en el que estás: ahí puedes quitar una receta, cambiar las opciones de la ruta o dejarla."] = "Die ganze Route beim aktuellen Schritt: Dort kannst du ein Rezept entfernen, die Routenoptionen ändern oder sie verlassen.",
  ["Clic: la explicación, paso a paso."] = "Klick: die ganze Erklärung, Schritt für Schritt.",
  ["Te guía paso a paso por tu ruta empezada, sin abrir la ventana: enseña el mismo paso que la vista Ruta."] = "Er führt dich Schritt für Schritt durch deine begonnene Route, ohne das Fenster zu öffnen: Er zeigt denselben Schritt wie die Routen-Ansicht.",
  ["Bloquearlo o sacarlo solo al empezar una ruta: /cj opciones, Asistente de ruta."] = "Sperren oder nur beim Start einer Route zeigen: /cj options, Routen-Assistent.",
  ["Un clic en el banner hace lo que toca"] = "Ein Klick auf das Banner erledigt den Schritt",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra; con el banco, saca a las bolsas justo lo que falta. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "Mit offenem AH kauft er das nächste Material, beim Händler kauft er dort, in der Bank holt er genau das in deine Taschen, was fehlt. Ist nichts offen, führt er dich zum nächsten NPC. Er kauft nie ohne deinen Klick.",
  ["El color dice qué toca"] = "Die Farbe zeigt, was ansteht",
  ["¿Por qué pide más fabricaciones de las que me dan los materiales?"] = "Warum verlangt er mehr Herstellungen, als meine Materialien hergeben?",
  ["La ruta compra por tandas: en las recetas amarillas y verdes no todas suben punto. \"Esta tanda: N\" es para cuántas te llega lo que llevas. Con suerte basta; si no, al acabarla te manda a comprar más."] = "Die Route kauft in Chargen: bei gelben und grünen Rezepten gibt nicht jede Herstellung einen Punkt. \"Diese Charge: N\" ist, wofür das reicht, was du dabeihast. Mit Glück genügt es; sonst schickt er dich danach mehr kaufen.",
  ["¿Qué significa el número de \"Fabrica N×\"?"] = "Was bedeutet die Zahl in \"Herstellen N×\"?",
  ["Es lo que te falta de media para acabar el paso, según los puntos que te quedan. Baja con cada fabricación; si tienes mala suerte y el punto no sube, se queda quieto hasta que lo subas."] = "So viele Herstellungen brauchst du im Schnitt noch, um den Schritt abzuschließen, nach den Punkten, die dir fehlen. Sie sinkt mit jeder Herstellung; hast du Pech und der Punkt kommt nicht, bleibt sie stehen, bis du ihn bekommst.",
  ["Lo tengo de otro sitio (comercio, hermandad, otro personaje)"] = "Ich habe es woanders her (Handelschat, Gilde, anderer Charakter)",
  ["En el paso de compra, pulsa Saltar: lo da por comprado en este tramo. Lo comprado en la AH ya cuenta aunque siga en el correo."] = "Klicke im Kaufschritt auf Überspringen: er zählt es für diesen Abschnitt als gekauft. Im AH Gekauftes zählt schon, solange es noch in der Post liegt.",
  ["¿Y si fabrico otra cosa o voy por otro orden?"] = "Und wenn ich etwas anderes herstelle oder eine andere Reihenfolge nehme?",
  ["La ruta mira tu nivel y tus bolsas, no lo que fabricaste: se pone al día sola. Si gastaste materiales, te mandará a comprar lo que falte."] = "Die Route schaut auf deine Stufe und deine Taschen, nicht darauf, was du hergestellt hast: sie passt sich selbst an. Hast du Materialien verbraucht, schickt sie dich kaufen, was fehlt.",
  ["Comprar o ir al banco"] = "Kaufen oder zur Bank",
  ["Ir a un PNJ"] = "Zu einem NPC",
  ["La flecha te lleva al PNJ"] = "Der Pfeil führt dich zum NPC",
  ["Sale cuando el paso tiene un PNJ: verde si vas bien, roja si vas al revés. También lo marca en el mapa y el minimapa. En otro continente te dice qué barco o zepelín tomar."] = "Er erscheint, wenn der Schritt einen NPC hat: grün in der richtigen Richtung, rot in der falschen. Er wird auch auf Karte und Minikarte markiert. Auf einem anderen Kontinent sagt er dir, welches Schiff oder welchen Zeppelin du nehmen musst.",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "Mit offenem AH kauft er das nächste Material, beim Händler kauft er dort. Ist nichts offen, führt er dich zum nächsten NPC. Er kauft nie ohne deinen Klick.",
  ["Comprar"] = "Kaufen",
  ["Comprar: por tramos"] = "Kaufen: pro Abschnitt",
  ["Comprar: ruta entera"] = "Kaufen: ganze Route",
  ["Saltar este paso"] = "Diesen Schritt überspringen",
  ["Recuperar"] = "Zurückholen",
  ["Recuperar este paso"] = "Diesen Schritt zurückholen",
  ["Lo saltaste: vuelve a pedirte comprarlo."] = "Du hast ihn übersprungen: Er fordert dich wieder zum Kaufen auf.",
  ["Si te equivocas, vuelve a él con la flecha de paso anterior y pulsa Recuperar."] = "Falls du dich vertan hast: Mit dem Pfeil zum vorigen Schritt zurück und Zurückholen drücken.",
  ["Saltado · Recuperar lo vuelve a poner"] = "Übersprungen · Zurückholen bringt ihn zurück",
  ["Lo das por comprado y pasa al siguiente paso. Para lo que el addon no ve (el chat de comercio, el banco de hermandad, un alter). Solo en este tramo."] = "Zählt als gekauft und geht zum nächsten Schritt. Für das, was das Addon nicht sieht (Handelschat, Gildenbank, ein Twink). Nur für diesen Abschnitt.",
  ["Lo comprado en la AH ya cuenta aunque siga en el correo."] = "Im AH Gekauftes zählt schon, solange es noch in der Post liegt.",
  ["Quitar de Ganar dinero"] = "Aus Geld verdienen entfernen",
  ["No volver a proponer esta receta aquí: por ejemplo, si pide una estación que no tienes. Se recupera con la fila de recetas quitadas, al final de la lista."] = "Dieses Rezept hier nicht mehr vorschlagen: zum Beispiel, wenn es eine Station braucht, die du nicht hast. Zurückholen mit der Zeile der entfernten Rezepte am Ende der Liste.",
  ["Recetas quitadas de Ganar dinero: %d"] = "Aus Geld verdienen entfernte Rezepte: %d",
  ["Quitadas de Ganar dinero"] = "Aus Geld verdienen entfernt",
  ["En las recetas verdes (y a veces en las amarillas) no todas las fabricaciones suben punto, así que la ruta compra por tandas: cuando gastas una, te trae a comprar la siguiente y luego vuelves a fabricar."] = "Bei grünen (und manchmal gelben) Rezepten gibt nicht jede Herstellung einen Punkt, deshalb kauft die Route in Chargen: Wenn du eine aufgebraucht hast, bringt sie dich zum Kauf der nächsten, und dann stellst du weiter her.",
  ["BETA"] = "BETA",
  ["Asistente de ruta (beta)"] = "Routen-Assistent (Beta)",
  ["Está en pruebas. Si ves algo raro, abre un post en el canal de bugs de nuestro Discord: el enlace está en el botón Informar de un error, arriba a la izquierda de la ventana del addon."] = "Er ist im Test. Wenn dir etwas seltsam vorkommt, eröffne einen Beitrag im Bugs-Kanal unseres Discords: den Link findest du hinter dem Knopf Fehler melden, oben links im Addon-Fenster.",
  ["Si no quieres usarlo, desactívalo en /cj opciones, Asistente de ruta."] = "Wenn du ihn nicht nutzen willst, schalte ihn unter /cj Optionen, Routen-Assistent ab.",
  ["los %d que hacen falta"] = "alle %d, die du brauchst",
  ["%d en total · tienes %d"] = "%d insgesamt · du hast %d",
  ["%d en total"] = "%d insgesamt",
  ["Demanda (TSM, región): ~%s vendidos al día, tasa de venta %s"] = "Nachfrage (TSM, Region): ~%s verkauft pro Tag, Verkaufsrate %s",
  ["Demanda (TSM): sin datos de este objeto (¿la app de TSM está al día?)"] = "Nachfrage (TSM): keine Daten für diesen Gegenstand (ist die TSM-App aktuell?)",
  ["TSM: en la región se vende de media a %s, bastante menos que los %s con los que se cuenta aquí."] = "TSM: in der Region wird es im Schnitt für %s verkauft, deutlich unter den %s, mit denen hier gerechnet wird.",
  ["Poca demanda según TSM y otra alerta en contra: aunque el margen parezca bueno, probablemente no lo venderás."] = "Geringe Nachfrage laut TSM und ein weiteres Warnzeichen: auch wenn die Marge gut aussieht, wirst du es wahrscheinlich nicht verkaufen.",
  ["TSM: en la región se venden ~%s al día: como mucho lo que se vende en %d días."] = "TSM: in der Region werden ~%s pro Tag verkauft: höchstens so viel, wie in %d Tagen verkauft wird.",
  ["Usar la demanda de TSM"] = "TSM-Nachfragedaten verwenden",
  ["Si tienes TSM con su app de escritorio: cuántos se venden al día en la región y qué parte de lo que se anuncia se vende. Es una alerta más de mercado y no se proponen más de los que se venden en 2 días. Tus escaneos siguen mandando."] = "Wenn du TSM mit seiner Desktop-App hast: wie viele pro Tag in der Region verkauft werden und welcher Anteil der Auktionen sich verkauft. Das ist ein weiteres Marktwarnzeichen, und es wird nie mehr vorgeschlagen, als in 2 Tagen verkauft wird. Deine eigenen Scans haben weiterhin Vorrang.",
  ["receta con enfriamiento, una cada vez."] = "Rezept mit Abklingzeit, eins nach dem anderen.",
  ["No se sabe aún si su enfriamiento está listo: al abrir la profesión se comprueba (si no lo está, sale del lote)."] = "Noch unbekannt, ob die Abklingzeit bereit ist: das wird beim Öffnen des Berufs geprüft (wenn nicht, fällt es aus dem Stapel).",
  [" · enfriamiento: ¿listo?"] = " · Abklingzeit: bereit?",
  [" · enfriamiento listo"] = " · Abklingzeit bereit",
  ["Abre la profesión para saber si está listo"] = "Öffne den Beruf, um zu sehen, ob es bereit ist",
  ["Listo: está en el lote de hoy"] = "Bereit: ist im heutigen Stapel",
  ["Demanda de TSM: vendidos al día, mínimo"] = "TSM-Nachfrage: mindestens verkauft pro Tag",
  ["Por debajo, alerta de poca demanda (y no se propone aprender la receta). Cuenta toda la región: tu reino vende como mucho eso."] = "Darunter eine Warnung wegen geringer Nachfrage (und das Rezept wird nicht zum Lernen vorgeschlagen). Zählt die ganze Region: dein Realm verkauft höchstens so viel.",
  ["Demanda de TSM: tasa de venta mínima"] = "TSM-Nachfrage: minimale Verkaufsrate",
  ["Qué parte de lo que se anuncia acaba vendiéndose (1 = todo). Por debajo, alerta de poca demanda."] = "Welcher Anteil der Auktionen sich am Ende verkauft (1 = alle). Darunter eine Warnung wegen geringer Nachfrage.",
  ["%s al día"] = "%s pro Tag",
  ["No cuenta"] = "Aus",
  ["Tiene enfriamiento (una cada vez): lo que cuesta aprenderla se recupera en %d fabricaciones."] = "Hat eine Abklingzeit (eins nach dem anderen): was das Erlernen kostet, ist nach %d Herstellungen wieder drin.",
  ["Tiene enfriamiento: se puede fabricar una cada vez."] = "Hat eine Abklingzeit: du kannst eins nach dem anderen herstellen.",
  [" · con enfriamiento"] = " · mit Abklingzeit",
  ["Este vendedor no tiene: %s. Sigue la fila para ir a otro."] = "Dieser Händler hat nicht: %s. Folge der Zeile, um zu einem anderen zu gehen.",
  ["Nuevo: asistente de ruta (beta)"] = "Neu: Routen-Assistent (Beta)",
  ["Con una ruta empezada, un banner pequeño te dice qué toca: fabricar, comprar en la AH o al vendedor, recoger el correo o entrenar. Un clic lo hace o te lleva. Se abre con el botón junto a Dejar ruta o con /cj mini."] = "Mit einer begonnenen Route zeigt dir ein kleines Banner, was als Nächstes kommt: herstellen, im AH oder beim Händler kaufen, die Post abholen oder trainieren. Ein Klick erledigt es oder bringt dich hin. Öffnen mit dem Knopf neben Route verlassen oder mit /cj mini.",
  ["Cuánto se tarda en fabricar"] = "Wie lange das Herstellen dauert",
  ["Cada paso de la ruta dice cuánto tardas en fabricarlo, y la franja de arriba el tiempo de toda la ruta."] = "Jeder Schritt der Route zeigt, wie lange das Herstellen dauert, und die Leiste oben die Zeit für die ganze Route.",
  ["Lo que sacas vendiendo en la AH"] = "Was du im AH bekommst",
  ["Bajo el total de la ruta, \"con AH\" dice lo que te quedaría si vendes lo fabricado como aconseja la vista Profit, en la AH y al vendedor."] = "Unter der Summe der Route zeigt \"mit AH\", was dir bleibt, wenn du das Hergestellte so verkaufst, wie die Profit-Ansicht rät, im AH und beim Händler.",
  ["Menos verdes en las rutas"] = "Weniger Grün in den Routen",
  ["La ruta prefiere recetas seguras a tramos largos en verde: menos fabricaciones y menos viajes a comprar, por muy poco oro más."] = "Die Route bevorzugt sichere Rezepte statt langer grüner Abschnitte: weniger Herstellungen und weniger Wege zum Kaufen, für sehr wenig mehr Gold.",
  ["Vender, más fácil"] = "Verkaufen, einfacher",
  ["Vender todo vende todo de un clic, y lo que no tiene un precio fiable en la AH va al vendedor. Con Ctrl+clic derecho en una fila lo pasas de la AH al vendedor o al revés."] = "Alles verkaufen verkauft alles mit einem Klick, und was keinen verlässlichen AH-Preis hat, geht an den Händler. Mit Strg+Rechtsklick auf eine Zeile verschiebst du es vom AH zum Händler oder zurück.",
  ["Compras por tandas en verde"] = "Kauf in Chargen bei grünen Rezepten",
  ["En las recetas verdes compra por tandas, con algo de margen, y \"esta tanda: N\" dice para cuántas te llega lo que llevas. El tamaño de la tanda se cambia en /cj opciones, Lista de compra."] = "Bei grünen Rezepten kauft er in Chargen, mit etwas Puffer, und \"diese Charge: N\" sagt dir, für wie viele Herstellungen das reicht, was du dabeihast. Die Chargengröße änderst du unter /cj Optionen, Einkaufsliste.",
  ["Enfriamientos en el lote de hoy"] = "Abklingzeiten in der heutigen Charge",
  ["Las transmutaciones y la Mooncloth que tienes listas entran en el Lote de hoy, una cada vez, y vuelven solas cuando están otra vez listas. También salen en las recetas que podrías aprender."] = "Transmutationen und Mondstoff, die bereit sind, kommen in die Heutige Charge, eins nach dem anderen, und kehren von selbst zurück, wenn sie wieder bereit sind. Sie erscheinen auch bei den Rezepten, die du lernen könntest.",
  ["Confirmar antes de vender o comprar todo"] = "Bestätigen vor Alles verkaufen oder Alles kaufen",
  ["Vender todo, Comprar todo y vender al vendedor desde el Inventario preguntan antes. Cada aviso se quita con \"No volver a mostrar\" y se vuelve a activar en las opciones."] = "Alles verkaufen, Alles kaufen und das Verkaufen an den Händler aus dem Inventar fragen jetzt vorher nach. Jede Abfrage lässt sich mit \"Nicht mehr zeigen\" abschalten und in den Optionen wieder einschalten.",
  ["Quita recetas de Ganar dinero"] = "Rezepte aus Geld verdienen entfernen",
  ["Con la X de una fila, Ganar dinero deja de proponerte esa receta (por ejemplo, si pide una estación que no tienes). Se recupera con la fila del final de la lista."] = "Mit dem X einer Zeile schlägt Geld verdienen dieses Rezept nicht mehr vor (zum Beispiel, wenn es eine Station braucht, die du nicht hast). Zurück holst du es mit der Zeile am Ende der Liste.",
  ["Demanda de TSM"] = "TSM-Nachfrage",
  ["Si tienes TSM con su app, Ganar dinero tiene en cuenta cuántas se venden al día en tu región y no te propone fabricar más de lo que se vende. Los mínimos se ajustan en las opciones de Ganar dinero."] = "Wenn du TSM mit seiner App hast, berücksichtigt Geld verdienen, wie viele pro Tag in deiner Region verkauft werden, und schlägt nie mehr vor, als verkauft wird. Die Mindestwerte stellst du in den Optionen von Geld verdienen ein.",
  ["La bolsa de componentes cuenta"] = "Die Reagenzientasche zählt",
  ["Lo que llevas en la bolsa de componentes cuenta en la ruta, el Inventario y Ganar dinero, y \"Recoge el correo\" se completa aunque lo recogido vaya a esa bolsa."] = "Was du in der Reagenzientasche hast, zählt in der Route, im Inventar und bei Geld verdienen, und \"Post abholen\" wird erledigt, auch wenn das Abgeholte in diese Tasche geht.",
  ["Recetas con dos herramientas"] = "Rezepte mit zwei Werkzeugen",
  ["Los cascos de ingeniería piden el Blacksmith Hammer y la Arclight Spanner, y la ruta ya pide las dos."] = "Ingenieurshelme brauchen den Schmiedehammer und den Bogenlichtschraubenschlüssel, und die Route verlangt jetzt beide.",
  ["Gasta lo que sobra"] = "Reste verbrauchen",
  ["Al acabar un paso, si te sobran materiales y fabricar con ellos deja más que venderlos, la ruta te lo propone."] = "Wenn ein Schritt fertig ist und dir Materialien übrig bleiben, schlägt die Route vor, damit herzustellen, falls das mehr bringt als sie zu verkaufen.",
  ["Recetas de lo intermedio"] = "Rezepte für Zwischenprodukte",
  ["Si algo intermedio pide una receta que no sabes (Stonescale Oil), la ruta tiene una fila para aprenderla y cuenta su precio."] = "Braucht ein Zwischenprodukt ein Rezept, das du nicht kennst (Steinschuppenöl), hat die Route eine Zeile, um es zu lernen, und rechnet seinen Preis mit.",
  ["Confirmar al anunciar, más fiable"] = "Zuverlässigere Bestätigung beim Einstellen",
  ["El Sí anuncia antes de cerrar el aviso, el aviso se cierra al cerrar la AH o el vendedor, y ya no dice \"Anunciados\" si la AH no responde."] = "Ja stellt ein, bevor die Abfrage schließt, die Abfrage schließt sich mit dem AH oder dem Händler, und sie meldet nicht mehr \"eingestellt\", wenn das AH nicht antwortet.",
  ["Rutas que no se quedan en el 99%"] = "Routen bleiben nicht mehr bei 99 % hängen",
  ["Si el cálculo de una ruta falla, la página lo dice en vez de quedarse en \"Calculando la ruta… 99%\". E Ingeniería 1-300 vuelve a calcularse rápido."] = "Schlägt die Berechnung einer Route fehl, sagt die Seite das, statt bei \"Route wird berechnet… 99%\" zu bleiben. Und Ingenieurskunst 1-300 wird wieder schnell berechnet.",
  ["Herramientas en la lista de la compra"] = "Werkzeuge auf der Einkaufsliste",
  ["Si un paso pide una herramienta que no llevas (Arclight Spanner), va a la lista de la compra en vez de darla por hecha."] = "Braucht ein Schritt ein Werkzeug, das du nicht dabeihast (Bogenlichtschraubenschlüssel), kommt es auf die Einkaufsliste, statt vorausgesetzt zu werden.",
  ["Transmutaciones en otros idiomas"] = "Transmutationen in anderen Sprachen",
  ["Con el juego en español, alemán o francés, la ruta ya no pide 186 transmutaciones seguidas: reconoce su enfriamiento."] = "Mit dem Spiel auf Spanisch, Deutsch oder Französisch verlangt die Route nicht mehr 186 Transmutationen am Stück: sie erkennt ihre Abklingzeit.",
  ["Sin errores en mazmorras"] = "Keine Fehler in Dungeons",
  ["Las compras de la AH se leen del chat solo con la AH abierta: en mazmorras y en combate ya no salen errores."] = "AH-Käufe werden nur bei geöffnetem AH aus dem Chat gelesen: keine Fehler mehr in Dungeons und im Kampf.",
  -- Investments tab (InvestUI.lua, Invest.lua)
  ["Inversiones"] = "Investitionen",
  ["Precio al apuntar una compra o venta"] = "Preis beim Eintragen eines Kaufs oder Verkaufs",
  ["Lo que escribes en el precio: el total (lo que pagaste por todo) o el precio por unidad. En la ventana de compra o venta lo puedes cambiar cada vez."] = "Was du als Preis eingibst: den Gesamtpreis (was du für alles bezahlt hast) oder den Preis pro Stück. Im Kauf- oder Verkaufsfenster kannst du es jedes Mal ändern.",
  ["Último escaneo (%s): nada a este precio; lo más barato, %s"] = "Letzter Scan (%s): nichts zu diesem Preis; am günstigsten %s",
  ["Último escaneo (%s): %s u a este precio o menos"] = "Letzter Scan (%s): %s zu diesem Preis oder weniger",
  [" · el resto desde %s"] = " · der Rest ab %s",
  ["Farmeado"] = "Gefarmt",
  ["Nueva pestaña: Inversiones"] = "Neuer Reiter: Investitionen",
  ["Apunta lo que compras para revender (cantidad y precio, por unidad o total) y te dice tu precio medio y cuánto ganas o pierdes, neto de la comisión de la AH (5%)."] = "Trage ein, was du zum Weiterverkauf kaufst (Menge und Preis, pro Stück oder gesamt), und es zeigt dir deinen Durchschnittspreis und wie viel du gewinnst oder verlierst, abzüglich der AH-Gebühr (5%).",
  ["hoy"] = "heute",
  ["ayer"] = "gestern",
  ["Escribe la cantidad y el precio (por ejemplo 2.5 = 2s 50c, o 1g 20s). Si lo has farmeado, 0."] = "Gib Menge und Preis ein (zum Beispiel 2.5 = 2s 50c, oder 1g 20s). Selbst gefarmt: 0.",
  ["Solo tienes %d para vender."] = "Du hast nur %d zum Verkaufen.",
  ["Escribe la cantidad: un número entero mayor que 0."] = "Gib die Menge ein: eine ganze Zahl größer als 0.",
