  ["%s a la venta"] = "%s im Angebot",
  ["Día dudoso: mucho más barato que el día de antes y el de después (una subasta suelta). No cuenta."] = "Zweifelhafter Tag: viel billiger als der Tag davor und danach (eine einzelne Auktion). Zählt nicht.",
  ["Borrar este movimiento"] = "Diese Bewegung löschen",
