  ["Una fila por objeto: muchas de un vistazo, con menos scroll."] = "Eine Zeile pro Gegenstand: viele auf einen Blick, mit weniger Scrollen.",
  ["Dos por fila, con más detalle."] = "Zwei pro Zeile, mit mehr Details.",
  ["Objeto"] = "Gegenstand",
  ["Tienes"] = "Du hast",
  ["Tu cartera está vacía. Añade una compra: escribe el nombre del objeto en el buscador de arriba a la derecha."] = "Dein Portfolio ist leer. Füge einen Kauf hinzu: gib den Namen des Gegenstands oben rechts im Suchfeld ein.",
  ["Clic: ordenar por esta columna (otro clic: al revés)."] = "Klick: nach dieser Spalte sortieren (erneut klicken: umgekehrt).",
  ["Precio de %s: puede haber cambiado."] = "Preis von %s: kann sich geändert haben.",
  ["Tu precio medio y lo que ganas con cada objeto."] = "Dein Durchschnittspreis und was du mit jedem Gegenstand gewinnst.",
  ["%d sin precio: no cuentan en Vale hoy."] = "%d ohne Preis: zählen nicht bei Heute wert.",
  ["Tu cartera de inversiones en la AH: lo que compraste, a qué precio medio y cuánto ganas o pierdes con cada objeto."] = "Dein AH-Investmentportfolio: was du gekauft hast, zu welchem Durchschnittspreis und wie viel du mit jedem Gegenstand gewinnst oder verlierst.",
  -- Options: Tabs category (order and hide the main window's tabs)
  ["Pestañas"] = "Reiter",
  ["Ocultar"] = "Ausblenden",
  ["OCULTA"] = "AUSGEBLENDET",
  ["Clic: volver a mostrarla."] = "Klick: wieder anzeigen.",
  ["Clic: ocultarla."] = "Klick: ausblenden.",
  ["Arrastra la fila para cambiar el orden. La de arriba es la que se abre al abrir el addon."] = "Zeile ziehen, um die Reihenfolge zu ändern. Das Addon öffnet sich auf dem obersten Reiter.",
  ["Vuelve a poder ordenar las pestañas."] = "Zurück zum Sortieren der Reiter.",
  ["Elige qué pestañas no se ven: clic en cada una y luego Hecho. Su página sigue abriéndose desde la AH o el asistente de ruta."] = "Wähle, welche Reiter ausgeblendet werden: auf jeden klicken, dann Fertig. Ihre Seite öffnet sich weiterhin über das AH oder den Routenassistenten.",
  ["Tiene que quedar al menos una pestaña visible."] = "Mindestens ein Reiter muss sichtbar bleiben.",
  ["Lista de compra oculta: ya no tiene pestaña ni brilla al añadirle algo. La lista junto a la Casa de Subastas y la ventana del vendedor siguen igual."] = "Einkaufsliste ausgeblendet: Sie hat keinen Reiter mehr und leuchtet nicht, wenn etwas hinzukommt. Die Liste neben dem Auktionshaus und das Händlerfenster funktionieren wie bisher.",
  ["Ordena y oculta las pestañas"] = "Reiter sortieren und ausblenden",
  ["En opciones, Pestañas: arrastra las pestañas para ordenarlas y oculta las que no uses. El addon se abre en la de arriba."] = "In den Optionen, Reiter: Reiter zum Sortieren ziehen und nicht genutzte ausblenden. Das Addon öffnet sich auf dem obersten.",
  ["Sin precio: instala Auctionator"] = "Kein Preis: installiere Auctionator",
  ["No volver a mostrar este consejo"] = "Diesen Tipp nicht mehr anzeigen",
  ["Precios de tus últimos escaneos. Instala Auctionator para volver a escanear y tener el historial de precios."] = "Preise aus deinen letzten Scans. Installiere Auctionator, um wieder zu scannen und den Preisverlauf zu bekommen.",
  ["Sin precios de este objeto. Instala Auctionator para escanear la AH y ver su evolución."] = "Keine Preise für diesen Gegenstand. Installiere Auctionator, um das AH zu scannen und den Verlauf zu sehen.",
  ["Del historial de Auctionator"] = "Aus der Auctionator-Historie",
  ["De tu escaneo de %s"] = "Aus deinem Scan: %s",
  ["De tu escaneo"] = "Aus deinem Scan",
  ["Subida sin confirmar: más del triple que el día anterior. No cuenta hasta que se repita otro día."] = "Unbestätigter Anstieg: mehr als das Dreifache des Vortags. Zählt erst, wenn er sich an einem anderen Tag wiederholt.",
  ["Día dudoso: mucho más caro que el día de antes y el de después. No cuenta."] = "Zweifelhafter Tag: viel teurer als der Tag davor und danach. Zählt nicht.",
  ["Subida sin confirmar a %s: no cuenta hasta que se repita otro día."] = "Unbestätigter Anstieg auf %s: zählt erst, wenn er sich an einem anderen Tag wiederholt.",
  ["Sin precio: búscalo en Auctionator"] = "Kein Preis: in Auctionator suchen",
  ["Auctionator aún no tiene precios de este objeto: búscalo o escanea con Auctionator."] = "Auctionator hat noch keine Preise für diesen Gegenstand: such ihn oder scanne mit Auctionator.",
  ["Auctionator aún no deja otro escaneo completo: espera a que acabe su cuenta atrás."] = "Auctionator erlaubt noch keinen weiteren vollständigen Scan: warte, bis sein Countdown abgelaufen ist.",
  ["Instala Auctionator para escanear la AH: el addon lee su escaneo completo."] = "Installiere Auctionator, um das AH zu scannen: das Addon liest dessen vollständigen Scan.",
  ["Auctionator aún no está listo para escanear: espera un momento o vuelve a abrir la AH."] = "Auctionator ist noch nicht bereit zum Scannen: warte kurz oder öffne das AH erneut.",
  [" (con el escaneo de Auctionator)"] = " (mit dem Scan von Auctionator)",
  ["Escaneando con Auctionator... %d s"] = "Scanne mit Auctionator... %d s",
  ["Con Auctionator: el escaneo lo hace Auctionator (así guarda su historial de precios) y el addon lee esos mismos datos para todas las pestañas."] = "Mit Auctionator: Auctionator führt den Scan aus (so speichert es seine Preishistorie) und das Addon liest dieselben Daten für alle Reiter.",
  ["Precios del historial de Auctionator: se ponen al día cada vez que escaneas."] = "Preise aus der Auctionator-Historie: sie aktualisieren sich bei jedem Scan.",
  ["Mayús+clic: buscarlo en la AH"] = "Umschalt+Klick: im AH suchen",
}
